    fn path(name: &str) -> serde_json::Value {
        // Use both "name" and "path" to cover old and new format versions.
        serde_json::json!({ "resolved_path": { "name": name, "path": name, "id": 0, "args": null } })
    }

    fn path_with_args(name: &str, args: Vec<serde_json::Value>) -> serde_json::Value {
        let type_args: Vec<serde_json::Value> = args
            .into_iter()
            .map(|t| serde_json::json!({ "type": t }))
            .collect();
        serde_json::json!({
            "resolved_path": {
                "name": name,
                "path": name,
                "id": 0,
                "args": {
                    "angle_bracketed": {
                        "args": type_args,
                        "bindings": []
                    }
                }
            }
        })
    }

    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn borrowed(inner: serde_json::Value) -> serde_json::Value {
        serde_json::json!({ "borrowed_ref": { "lifetime": null, "mutable": false, "type_": inner } })
    }

    #[test]
    fn test_primitives() {
        assert_eq!(ipe(&prim("u64")), "Int");
        assert_eq!(ipe(&prim("usize")), "Int");
        assert_eq!(ipe(&prim("i32")), "Int");
        assert_eq!(ipe(&prim("f32")), "Float");
        assert_eq!(ipe(&prim("bool")), "Bool");
        assert_eq!(ipe(&prim("str")), "String");
    }

    #[test]
    fn test_string_path() {
        assert_eq!(ipe(&path("String")), "String");
        assert_eq!(ipe(&path("OsString")), "String");
    }

    #[test]
    fn owned_string_vs_borrowed_str_rust_type_distinct() {
        // [#67] The codegen's argCall branches on the host param's OWNED-vs-
        // BORROWED Rust type to decide between by-value (`Opts::new(arg0)`) and
        // borrowed (`fn(&arg0)` / `arg0.as_ref()`) passing. Both lower to the
        // SAME Ipe surface (`String`), so the only carrier of the distinction is
        // `rust_type`. Pin it: an OWNED `String` param renders `"String"`, a
        // borrowed `&str` renders `"&str"` — the exact pair argCall keys on.
        // (A regression here — e.g. owned String rendering `"&String"` — would
        // reintroduce the firestore `FirestoreDbOptions::new` E0308.)
        assert_eq!(rustdoc_type_to_rust_str(&path("String")), "String");
        assert_eq!(rustdoc_type_to_rust_str(&borrowed(prim("str"))), "&str");
        assert_eq!(
            rustdoc_type_to_rust_str(&borrowed(path("String"))),
            "&String"
        );
        // Both collapse to the Ipe `String` surface (proving the Ipe type alone
        // CANNOT distinguish owned from borrowed — `rust_type` must).
        assert_eq!(ipe(&path("String")), "String");
        assert_eq!(ipe(&borrowed(prim("str"))), "String");
    }

    #[test]
    fn test_generic_containers() {
        assert_eq!(ipe(&path_with_args("Vec", vec![prim("u64")])), "List Int");
        assert_eq!(
            ipe(&path_with_args("Option", vec![path("String")])),
            "Maybe String"
        );
        assert_eq!(
            ipe(&path_with_args(
                "HashMap",
                vec![path("String"), prim("u64")]
            )),
            "Dict String Int"
        );
    }

    #[test]
    fn test_path_qualified_and_nested_containers() {
        // Some rustdoc versions emit `std::collections::HashMap` (qualified);
        // it must still map to `Dict String _`, not the bare `HashMap`.
        assert_eq!(
            ipe(&path_with_args(
                "std::collections::HashMap",
                vec![path("String"), path("String")]
            )),
            "Dict String String"
        );
        // Vec<HashMap<String,String>> → List (Dict String String) — the nested
        // multi-word arg must be parenthesised.
        let inner = path_with_args("HashMap", vec![path("String"), path("String")]);
        assert_eq!(
            ipe(&path_with_args("Vec", vec![inner])),
            "List (Dict String String)"
        );
        // Result<HashMap<String,String>, String> → Result String (Dict String String)
        let ok = path_with_args("HashMap", vec![path("String"), path("String")]);
        assert_eq!(
            ipe(&path_with_args("Result", vec![ok, path("String")])),
            "Result String (Dict String String)"
        );
    }

    #[test]
    fn test_result_and_ipe_result() {
        // Rust Result<String, IpeError>  →  Ipe Result Error String
        let r = path_with_args("Result", vec![path("String"), path("IpeError")]);
        assert_eq!(ipe(&r), "Result Error String");

        // IpeResult<IpeError, String>  →  Ipe Result Error String
        let sr = path_with_args("IpeResult", vec![path("IpeError"), path("String")]);
        assert_eq!(ipe(&sr), "Result Error String");
    }

