    #[test]
    fn test_is_byte_seq() {
        assert!(is_byte_seq("&[u8]"));
        assert!(is_byte_seq("Vec<u8>"));
        assert!(is_byte_seq("[u8; 16]"));
        assert!(is_byte_seq("&[u8; 32]"));
        // Not byte sequences:
        assert!(!is_byte_seq("&mut [u8]"));
        assert!(!is_byte_seq("&[u16]"));
        assert!(!is_byte_seq("[f64; 3]"));
        assert!(!is_byte_seq("Vec<i64>"));
        assert!(!is_byte_seq("&str"));
    }

    #[test]
    fn test_is_coercible_seq() {
        // Byte sequences still recognised (regression w.r.t. v1's is_byte_seq):
        assert!(is_coercible_seq("&[u8]"));
        assert!(is_coercible_seq("Vec<u8>"));
        assert!(is_coercible_seq("[u8; 16]"));
        assert!(is_coercible_seq("&[u8; 32]"));

        // Non-byte coercible elements now accepted:
        assert!(is_coercible_seq("&[String]"));
        assert!(is_coercible_seq("Vec<String>"));
        assert!(is_coercible_seq("[f64; 3]"));
        assert!(is_coercible_seq("&[i32; 4]"));
        assert!(is_coercible_seq("&[i64]"));
        assert!(is_coercible_seq("Vec<bool>"));

        // Not coercible:
        assert!(!is_coercible_seq("&mut [u8]")); // mutable ref excluded
        assert!(!is_coercible_seq("&[Vec<String>]")); // nested generic elem (conservative drop)
        assert!(!is_coercible_seq("&[&str]")); // borrowed elem (lifetime concerns)
        assert!(!is_coercible_seq("[u8; abc]")); // non-digit N
        assert!(!is_coercible_seq("&str")); // not a sequence
        assert!(!is_coercible_seq(""));
    }

    #[test]
    fn test_setter_receives_losslessly() {
        // Lossless-receive set {i64, f64} + every non-numeric closed-set type.
        assert!(setter_receives_losslessly("i64"));
        assert!(setter_receives_losslessly("f64"));
        assert!(setter_receives_losslessly("bool"));
        assert!(setter_receives_losslessly("String"));
        assert!(setter_receives_losslessly("char"));
        assert!(setter_receives_losslessly("Vec<String>"));
        assert!(setter_receives_losslessly("Option<String>"));
        // An opaque whose NAME merely contains a numeric substring is NOT matched
        // (word-tokenised, so `Fu64` / `Mu32Val` are not `u64` / `u32`).
        assert!(setter_receives_losslessly("Fu64"));
        assert!(setter_receives_losslessly("MyType"));

        // Narrower-than-Ipe-scalar numerics → setter would truncate → dropped.
        for t in ["i8", "i16", "i32", "u8", "u16", "u32", "f32"] {
            assert!(!setter_receives_losslessly(t), "{t} setter must drop");
        }
        // Wider-than-i64 ints → reinterpret/overshoot → dropped (the #22 getter
        // is admitted, but the setter must stay dropped).
        for t in ["u64", "u128", "i128", "usize", "isize"] {
            assert!(!setter_receives_losslessly(t), "{t} setter must drop");
        }
        // CONTAINER-AWARE: the hazard survives one container level. An
        // `Option<u64>` / `Vec<u32>` setter lowers to `…map(|x| x as u64/u32)`,
        // reinterpreting/truncating the Ipe i64 — must stay dropped.
        assert!(!setter_receives_losslessly("Option<u64>"));
        assert!(!setter_receives_losslessly("Option<u32>"));
        assert!(!setter_receives_losslessly("Vec<u64>"));
        assert!(!setter_receives_losslessly("Vec<i128>"));
    }

    #[test]
    fn test_owned_copy_borrowed_return_gate() {
        // Mirror the `owned_copy_admissible` policy used by `is_result_borrow`.
        // (Inlined here as a closure since the real one is a local in
        // `parse_fn_item`; this test pins the EXACT admit/drop contract of #22 +
        // #110 which adds Option<&T> for Clone opaques.)
        let admit = |t: &str| -> bool {
            let t = t.trim();
            if t == "&str" || t == "&String" {
                return true;
            }
            if let Some(inner) = t.strip_prefix("Option<").and_then(|s| s.strip_suffix('>')) {
                let inner = inner.trim();
                if inner == "&str" || inner == "&String" {
                    return true;
                }
                // [#110] Option<&T> for a crate-local Clone opaque — treat Foo
                // as a Clone opaque for this unit (the real gate consults
                // CLONE_OPAQUE_NAMES; end-to-end covered by fixture 110).
                if let Some(rest) = inner.strip_prefix('&') {
                    let t_name = rest.trim();
                    return !t_name.starts_with("mut ")
                        && !t_name.starts_with('&')
                        && !t_name.contains('<');
                }
                return false;
            }
            if let Some(rest) = t.strip_prefix('&') {
                let rest = rest.trim();
                // Treat `Foo` as a derived-Clone opaque for this unit (the real
                // gate also consults CLONE_OPAQUE_NAMES — exercised end-to-end by
                // the 47-borrowed-returns fixture).
                return !rest.starts_with("mut ")
                    && !rest.starts_with('&')
                    && !rest.starts_with('(')
                    && !rest.starts_with('[')
                    && !rest.contains('<');
            }
            false
        };

        // ADMIT (owned-copy): plain &str/&String, Option<&str>/<&String>, &T,
        // and (#110) Option<&T> for Clone opaque T.
        assert!(admit("&str"));
        assert!(admit("&String"));
        assert!(admit("Option<&str>"));
        assert!(admit("Option<&String>"));
        assert!(admit("&NaiveDate"));
        assert!(admit("&chrono::NaiveDate"));
        assert!(admit("Option<&NaiveDate>")); // [#110] Clone opaque
        assert!(admit("Option<&toml::Value>")); // [#110] Clone opaque (qualified)

        // DROP (conservative-on-doubt): &mut, nested/tuple borrow, generic borrow,
        // Option<&mut T>, Option<nested borrow>, Option<generic>.
        assert!(!admit("&mut Builder"));
        assert!(!admit("&(A, B)"));
        assert!(!admit("&[u8]"));
        assert!(!admit("&Vec<u8>"));
        assert!(!admit("Option<&mut Value>")); // &mut inside Option → drop
        assert!(!admit("Option<&&Value>")); // nested borrow → drop
        assert!(!admit("Option<&Vec<u8>>")); // generic inside → drop
        assert!(!admit("&mut str"));
    }

    #[test]
    fn test_coercible_elem_gate_tightened() {
        // #22: the List-element gate admits ONLY closed-set numerics, bool,
        // char, String (each soundly coerced per-element by translateRustRet),
        // plus a crate-local Clone opaque (via CLONE_OPAQUE_NAMES — empty in
        // this unit, so opaque names correctly DROP here). Pins the removal of
        // the old blanket "any identifier" catch-all that admitted non-Clone
        // opaque elements → E0599 cargo-fail.

        // ADMIT — numerics (incl. the wide ones now per-element saturated).
        for t in [
            "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize",
            "f32", "f64", "bool", "char", "String",
        ] {
            assert!(is_ipe_coercible_elem(t), "should admit {t}");
        }

        // DROP — str (unsized: no Vec<str>), OsString/PathBuf (not Ipe-closed),
        // and any opaque (CLONE_OPAQUE_NAMES empty in this unit → not Clone-proven).
        for t in [
            "str",
            "OsString",
            "PathBuf",
            "Foo",
            "NaiveDate",
            "_Hidden",
            "f128",
        ] {
            assert!(!is_ipe_coercible_elem(t), "should DROP {t}");
        }

        // Markers still reject.
        assert!(!is_ipe_coercible_elem("&u8"));
        assert!(!is_ipe_coercible_elem("Vec<u8>"));
        assert!(!is_ipe_coercible_elem(""));
    }

    fn trait_bound(path: &str, args: Vec<serde_json::Value>) -> serde_json::Value {
        let type_args: Vec<_> = args
            .into_iter()
            .map(|t| serde_json::json!({ "type": t }))
            .collect();
        serde_json::json!({ "trait_bound": { "trait": {
            "path": path, "name": path, "id": 0,
            "args": { "angle_bracketed": { "args": type_args, "constraints": [] } }
        }, "modifier": "none" } })
    }

    #[test]
    fn test_bound_to_concrete() {
        // AsRef<[u8]> / Borrow<[u8]>  -> Vec<u8> (List Int)
        let asref_u8 = trait_bound(
            "AsRef",
            vec![serde_json::json!({ "slice": { "primitive": "u8" } })],
        );
        assert_eq!(
            bound_to_concrete(&asref_u8, BoundPos::Param),
            Some(vec_u8_node())
        );
        // AsRef<str> / Borrow<str>    -> String (PARAM: call site does `.as_ref()`)
        assert_eq!(
            bound_to_concrete(&trait_bound("AsRef", vec![prim("str")]), BoundPos::Param),
            Some(string_node())
        );
        // [#73, C-R] AsRef/Borrow in RETURN position DROP (None): an anonymous
        // `impl AsRef<str>` return can't be owned by the codegen body (needs a
        // `.as_ref().to_string()` coercion it lacks) → fail-closed, like iterators.
        assert_eq!(
            bound_to_concrete(&trait_bound("AsRef", vec![prim("str")]), BoundPos::Return),
            None
        );
        assert_eq!(
            bound_to_concrete(&trait_bound("Borrow", vec![prim("str")]), BoundPos::Return),
            None
        );
        // AsRef<[u8]> also drops at Return (same coercion gap).
        assert_eq!(bound_to_concrete(&asref_u8, BoundPos::Return), None);
        // Into in RETURN position is UNAFFECTED by the C-R AsRef drop (separate case).
        assert_eq!(
            bound_to_concrete(&trait_bound("Into", vec![path("String")]), BoundPos::Return),
            Some(string_node())
        );
        // Display / ToString (no arg) -> String
        assert_eq!(
            bound_to_concrete(&trait_bound("Display", vec![]), BoundPos::Param),
            Some(string_node())
        );
        assert_eq!(
            bound_to_concrete(&trait_bound("ToString", vec![]), BoundPos::Param),
            Some(string_node())
        );
        // Into<Vec<u8>> -> Vec<u8> ; Into<String> -> String
        assert_eq!(
            bound_to_concrete(
                &trait_bound("Into", vec![path_with_args("Vec", vec![prim("u8")])]),
                BoundPos::Param
            ),
            Some(vec_u8_node())
        );
        assert_eq!(
            bound_to_concrete(&trait_bound("Into", vec![path("String")]), BoundPos::Param),
            Some(string_node())
        );
        // Unknown / unsupported -> None
        assert_eq!(
            bound_to_concrete(&trait_bound("FromStr", vec![]), BoundPos::Param),
            None
        );
        // AsRef<u16> drops — the v2 soundness gate restored after 09-bytesize
        // showed `i64: AsRef<u16>` doesn't exist. v1's drop behaviour is restored
        // for AsRef<primitive_non_str>.
        assert_eq!(
            bound_to_concrete(&trait_bound("AsRef", vec![prim("u16")]), BoundPos::Param),
            None
        );
        // A truly unsupported inner type still returns None
        assert_eq!(
            bound_to_concrete(
                &trait_bound(
                    "AsRef",
                    vec![
                        serde_json::json!({ "resolved_path": { "name": "SomeWeirdType", "path": "SomeWeirdType", "id": 0, "args": null } })
                    ]
                ),
                BoundPos::Param
            ),
            None
        );

        // [#78 WALL-E] Into<&'static str> / From<&str> drop — a runtime owned Ipe
        // value can never BECOME a borrowed reference (firebase
        // `ApiUriBuilder::build<PathT: Into<&'static str>>`). `String:
        // Into<&'static str>` is false, so substituting String is E0277.
        let static_str = serde_json::json!({
            "borrowed_ref": { "lifetime": "'static", "is_mutable": false, "type": { "primitive": "str" } }
        });
        assert_eq!(
            bound_to_concrete(
                &trait_bound("Into", vec![static_str.clone()]),
                BoundPos::Param
            ),
            None,
            "Into<&'static str> must DROP — String can lend but never become a &'static str"
        );
        let elided_str = serde_json::json!({
            "borrowed_ref": { "lifetime": null, "is_mutable": false, "type": { "primitive": "str" } }
        });
        assert_eq!(
            bound_to_concrete(&trait_bound("From", vec![elided_str]), BoundPos::Param),
            None,
            "From<&str> must DROP — same borrowed-target soundness hole as the 'static case"
        );
        // CONTRAST: AsRef<&str>-shaped borrowed target KEEPS the see-through —
        // lending an &str is exactly what AsRef means (String: AsRef<str>).
        assert_eq!(
            bound_to_concrete(&trait_bound("AsRef", vec![static_str]), BoundPos::Param),
            Some(string_node()),
            "AsRef sees through a borrowed target — only Into/From drop on it"
        );
    }

    #[test]
    fn test_resolve_param_bounds() {
        let asref_u8 = trait_bound(
            "AsRef",
            vec![serde_json::json!({ "slice": { "primitive": "u8" } })],
        );
        let clone = trait_bound("Clone", vec![]);
        let send = trait_bound("Send", vec![]);
        let foo = trait_bound("SomeWeirdTrait", vec![]);
        let asref_str = trait_bound("AsRef", vec![prim("str")]);

        // shape bound alone -> resolves
        assert_eq!(
            resolve_param_bounds(std::slice::from_ref(&asref_u8), BoundPos::Param),
            Some(vec_u8_node())
        );
        // shape + marker bounds -> markers ignored, resolves
        assert_eq!(
            resolve_param_bounds(&[asref_u8.clone(), clone.clone(), send], BoundPos::Param),
            Some(vec_u8_node())
        );
        // only markers -> can't pin a type -> None
        assert_eq!(resolve_param_bounds(&[clone], BoundPos::Param), None);
        // an unknown non-marker bound -> None (unsound to guess)
        assert_eq!(
            resolve_param_bounds(&[asref_u8.clone(), foo], BoundPos::Param),
            None
        );
        // two conflicting shape bounds -> None
        assert_eq!(
            resolve_param_bounds(&[asref_u8, asref_str], BoundPos::Param),
            None
        );
    }

    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn type_param(name: &str, bounds: Vec<serde_json::Value>) -> serde_json::Value {
        serde_json::json!({ "name": name, "kind": { "type": { "bounds": bounds, "default": null, "is_synthetic": false } } })
    }
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn fn_with_generics(
        params: Vec<serde_json::Value>,
        wheres: Vec<serde_json::Value>,
    ) -> serde_json::Value {
        serde_json::json!({ "generics": { "params": params, "where_predicates": wheres } })
    }

    #[test]
    fn test_resolve_generics() {
        let asref_u8 = trait_bound(
            "AsRef",
            vec![serde_json::json!({ "slice": { "primitive": "u8" } })],
        );
        let display = trait_bound("Display", vec![]);

        // no generics -> empty map (Some)
        assert_eq!(
            resolve_generics(&fn_with_generics(vec![], vec![])),
            Some(std::collections::HashMap::new())
        );

        // <T: AsRef<[u8]>> -> {T: Vec<u8>}
        let r = resolve_generics(&fn_with_generics(
            vec![type_param("T", vec![asref_u8.clone()])],
            vec![],
        ))
        .unwrap();
        assert_eq!(r.get("T"), Some(&vec_u8_node()));

        // two params both resolve
        let r2 = resolve_generics(&fn_with_generics(
            vec![
                type_param("T", vec![asref_u8.clone()]),
                type_param("U", vec![display]),
            ],
            vec![],
        ))
        .unwrap();
        assert_eq!(r2.get("T"), Some(&vec_u8_node()));
        assert_eq!(r2.get("U"), Some(&string_node()));

        // unresolvable bound -> None (drop whole fn)
        assert_eq!(
            resolve_generics(&fn_with_generics(
                vec![type_param("T", vec![trait_bound("FromStr", vec![])])],
                vec![]
            )),
            None
        );

        // const generic present -> None
        let const_p = serde_json::json!({ "name": "N", "kind": { "const": { "type": { "primitive": "usize" } } } });
        assert_eq!(
            resolve_generics(&fn_with_generics(vec![const_p], vec![])),
            None
        );

        // bound supplied via where-predicate instead of inline
        let wp = serde_json::json!({ "bound_predicate": { "type": { "generic": "T" }, "bounds": [asref_u8] } });
        let r3 =
            resolve_generics(&fn_with_generics(vec![type_param("T", vec![])], vec![wp])).unwrap();
        assert_eq!(r3.get("T"), Some(&vec_u8_node()));
    }

    #[test]
    fn test_subst_generic_json() {
        let mut map = std::collections::HashMap::new();
        map.insert("T".to_string(), vec_u8_node());
        // bare {generic:"T"} -> Vec<u8>
        assert_eq!(
            subst_generic_json(
                &serde_json::json!({ "generic": "T" }),
                &map,
                BoundPos::Param
            ),
            vec_u8_node()
        );
        // nested Option<T> -> Option<Vec<u8>>: the T node deep inside is replaced
        let opt_t = path_with_args("Option", vec![serde_json::json!({ "generic": "T" })]);
        let got = subst_generic_json(&opt_t, &map, BoundPos::Param);
        // Nested multi-word generic arg is parenthesised so Ipe's
        // left-associative type application parses it as one argument.
        assert_eq!(ipe(&got), "Maybe (List Int)");
        // an unrelated generic "U" not in map is left intact
        assert_eq!(
            subst_generic_json(
                &serde_json::json!({ "generic": "U" }),
                &map,
                BoundPos::Param
            ),
            serde_json::json!({ "generic": "U" })
        );
    }

    // Build a function item shaped like rustdoc's: encode<T: AsRef<[u8]>>(data: T) -> String
    fn encode_fn_data() -> serde_json::Value {
        let asref_u8 = trait_bound(
            "AsRef",
            vec![serde_json::json!({ "slice": { "primitive": "u8" } })],
        );
        serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false },
            "generics": { "params": [ type_param("T", vec![asref_u8]) ], "where_predicates": [] },
            "sig": { "inputs": [ ["data", { "generic": "T" }] ], "output": prim("str") }
        })
    }

    #[test]
    fn test_parse_fn_item_monomorphises() {
        let f = parse_fn_item("encode", &encode_fn_data(), &HashMap::new(), None)
            .expect("encode<T:AsRef<[u8]>> should now bind, not drop");
        assert_eq!(f.name, "encode");
        assert_eq!(f.params.len(), 1);
        assert_eq!(f.params[0].ipe_type, "List Int"); // T -> Vec<u8> -> List Int
        assert_eq!(f.params[0].rust_type, "Vec<u8>");
        assert_eq!(f.results[0].ipe_type, "String"); // -> str -> String
    }

