    // ── private-path-admission — an external TRAIT def-path threading a
    //    private module of a NON-std crate must NOT be recorded as a UFCS
    //    qualifier (E0603 if reached); a root-public external trait still is.
    #[test]
    fn external_trait_private_module_path_is_dropped_at_admission() {
        let doc = serde_json::json!({
            "index": {
                "1": { "name": "mycrate", "crate_id": 0, "visibility": "public",
                       "inner": { "module": { "items": [] } } }
            },
            "paths": {
                // Root-public foreign trait — the public path IS the def path.
                "200": { "crate_id": 1, "kind": "trait",
                         "path": ["reqwest", "IntoUrl"] },
                // Foreign trait whose def path threads a PRIVATE module; the
                // public re-export lives at an ancestor whose visibility we
                // cannot read without reqwest's own rustdoc.
                "201": { "crate_id": 1, "kind": "trait",
                         "path": ["reqwest", "async_impl", "client", "Fluent"] }
            },
        });
        let paths = collect_external_trait_paths(&doc);
        assert_eq!(
            paths.get("200").map(String::as_str),
            Some("reqwest::IntoUrl"),
            "a root-public external trait keeps its verbatim public path"
        );
        assert!(
            !paths.contains_key("201"),
            "a private-module-threading external trait must be DROPPED at admission \
             (absent from the map → TraitUnreachable), got {:?}",
            paths.get("201")
        );
    }

    #[test]
    fn external_std_trait_multisegment_still_recorded() {
        // The fix must NOT regress a legitimate std/core trait whose public path
        // coincides with its multi-segment def path.
        let doc = serde_json::json!({
            "index": {
                "1": { "name": "mycrate", "crate_id": 0, "visibility": "public",
                       "inner": { "module": { "items": [] } } }
            },
            "paths": {
                "300": { "crate_id": 1, "kind": "trait",
                         "path": ["core", "convert", "From"] },
                // The known private std re-export submodule still collapses.
                "301": { "crate_id": 1, "kind": "trait",
                         "path": ["core", "str", "traits", "FromStr"] }
            },
        });
        let paths = collect_external_trait_paths(&doc);
        assert_eq!(
            paths.get("300").map(String::as_str),
            Some("core::convert::From")
        );
        assert_eq!(
            paths.get("301").map(String::as_str),
            Some("core::str::FromStr"),
            "the core::str::traits private re-export must still collapse to public"
        );
    }

    /// A rustdoc `doc` whose `paths` table carries:
    ///   id 100 → external `core::clone::Clone` (the real std trait)
    ///   id 101 → external `core::fmt::Display`
    ///   id 102 → external `core::str::FromStr`
    ///   id  10 → crate-local `Clone`   (the crate's OWN trait, `crate_id` 0)
    ///   id  11 → crate-local `Display` (the crate's OWN trait, `crate_id` 0)
    fn doc_with_traits() -> serde_json::Value {
        serde_json::json!({
            "index": {
                "10": { "crate_id": 0, "inner": { "trait": {} } },
                "11": { "crate_id": 0, "inner": { "trait": {} } }
            },
            "paths": {
                "100": { "crate_id": 1, "kind": "trait", "path": ["core", "clone", "Clone"] },
                "101": { "crate_id": 2, "kind": "trait", "path": ["core", "fmt", "Display"] },
                "102": { "crate_id": 2, "kind": "trait", "path": ["core", "str", "FromStr"] },
                "10":  { "crate_id": 0, "kind": "trait", "path": ["mycrate", "Clone"] },
                "11":  { "crate_id": 0, "kind": "trait", "path": ["mycrate", "Display"] }
            }
        })
    }

    #[test]
    fn test_std_trait_tag_external_recognized() {
        // Control: the REAL std Clone/Display/FromStr (crate_id>0, canonical path)
        // MUST still resolve to their std tag.
        let doc = doc_with_traits();
        with_doc_provenance(&doc, || {
            let clone = trait_bound_id("Clone", 100);
            let display = trait_bound_id("Display", 101);
            let fromstr = trait_bound_id("FromStr", 102);
            assert_eq!(
                std_trait_tag(clone.get("trait_bound").unwrap().get("trait").unwrap()),
                Some("Clone")
            );
            assert_eq!(
                std_trait_tag(display.get("trait_bound").unwrap().get("trait").unwrap()),
                Some("Display")
            );
            assert_eq!(
                std_trait_tag(fromstr.get("trait_bound").unwrap().get("trait").unwrap()),
                Some("FromStr")
            );
        });
    }

    #[test]
    fn test_std_trait_tag_crate_local_not_std() {
        // #25 DEFECT: a crate-local trait named `Clone`/`Display` (crate_id 0) must
        // NOT resolve to the std tag — its id is in LOCAL_TYPE_IDS.
        let doc = doc_with_traits();
        with_doc_provenance(&doc, || {
            let local_clone = trait_bound_id("Clone", 10);
            let local_display = trait_bound_id("Display", 11);
            assert_eq!(
                std_trait_tag(
                    local_clone
                        .get("trait_bound")
                        .unwrap()
                        .get("trait")
                        .unwrap()
                ),
                None,
                "crate-local `Clone` must not be treated as std Clone"
            );
            assert_eq!(
                std_trait_tag(
                    local_display
                        .get("trait_bound")
                        .unwrap()
                        .get("trait")
                        .unwrap()
                ),
                None,
                "crate-local `Display` must not be treated as std Display"
            );
        });
    }

