        let method_g = generics_obj(vec![], vec![]);
        let wp = serde_json::json!({ "bound_predicate": {
            "type": { "qualified_path": { "name": "Item", "self_type": gnode("K") } },
            "bounds": [trait_bound("Hash", vec![])] } });
