    #[test]
    fn test_parametric_stub_closure_with_send_companion_drops() {
        // The canonical async/threadpool shape `F: Fn(A)->B + Send`. A synthesized
        // Ipe closure can't honour `Send`, so binding it would emit a wrapper whose
        // call is E0277 at the foreign fn (a cargo-FAIL). The closure-slot detector
        // must REFUSE the slot (companion not satisfiable) → the param falls through
        // to the existing UnmodellableBound("Fn") safe drop. Over-drop, not
        // under-bind. (Guardian-flagged soundness gate, epic #28.)
        // F's bound list = the Fn closure bound PLUS a `Send` marker companion.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("A", vec![]),
                type_param("B", vec![]),
                type_param("F", vec![
                    closure_bound("Fn", vec![gnode("A")], Some(gnode("B"))),
                    trait_bound("Send", vec![]),
                ]),
            ], "where_predicates": [] },
            "sig": { "inputs": [
                ["xs", path_with_args("Vec", vec![gnode("A")])],
                ["f", gnode("F")]
            ], "output": path_with_args("Vec", vec![gnode("B")]) }
        });
        match try_parametric_stub(
            "map_each",
            &fd,
            Some(("Foo", "::clo::Foo")),
            None,
            None,
            None,
        ) {
            Err(GenericDrop::UnmodellableBound(t)) => assert_eq!(t, "Fn"),
            other => panic!("expected UnmodellableBound(\"Fn\") safe drop, got {other:?}"),
        }
    }

    #[test]
    fn test_parametric_stub_closure_with_lifetime_companion_binds() {
        // A `'static` outlives companion (no trait name) IS satisfiable by an
        // owned-capture Ipe closure → still binds. Confirms the gate admits
        // lifetime bounds, only rejecting unsatisfiable TRAIT companions.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("A", vec![]),
                type_param("B", vec![]),
                // F: Fn(A)->B + 'static  (the outlives bound carries no trait name)
                type_param("F", vec![
                    closure_bound("Fn", vec![gnode("A")], Some(gnode("B"))),
                    serde_json::json!({ "outlives": "'static" }),
                ]),
            ], "where_predicates": [] },
            "sig": { "inputs": [
                ["xs", path_with_args("Vec", vec![gnode("A")])],
                ["f", gnode("F")]
            ], "output": path_with_args("Vec", vec![gnode("B")]) }
        });
        let stub = try_parametric_stub(
            "map_each",
            &fd,
            Some(("Foo", "::clo::Foo")),
            None,
            None,
            None,
        )
        .expect("Fn + 'static must still bind");
        assert!(
            stub.call
                .arg_types
                .iter()
                .any(|t| matches!(t, TypeRef::Closure { .. }))
        );
    }

    // ── epic #30: iterator-param seam ──────────────────────────────────

    #[test]
    fn iterator_bound_of_detects_both_kinds() {
        // A single IntoIterator bound → IntoIter; a single Iterator bound → Iter.
        let into = vec![iter_bound("IntoIterator", primitive("i64"))];
        let (k, _) = iterator_bound_of(&into).expect("IntoIterator slot detected");
        assert_eq!(k, IterKind::IntoIter);
        let it = vec![iter_bound("Iterator", primitive("i64"))];
        let (k2, _) = iterator_bound_of(&it).expect("Iterator slot detected");
        assert_eq!(k2, IterKind::Iter);
        // A non-iterator bound list → None (ordinary tyvar path).
        assert!(iterator_bound_of(&[trait_bound("Clone", vec![])]).is_none());
        // Two iterator bounds on one param → None (not a plain slot).
        assert!(
            iterator_bound_of(&[
                iter_bound("IntoIterator", primitive("i64")),
                iter_bound("Iterator", primitive("i64")),
            ])
            .is_none()
        );
    }

    #[test]
    fn iterator_bound_of_rejects_unsatisfiable_companion() {
        // [C5] `I: Iterator + Send` → NOT a bindable iterator slot (a `Vec` arg
        // can't carry an arbitrary companion the host might rely on) → None →
        // the param falls through to the existing safe UnmodellableBound drop.
        let send = vec![
            iter_bound("Iterator", primitive("i64")),
            trait_bound("Send", vec![]),
        ];
        assert!(iterator_bound_of(&send).is_none());
        // A `Sized` companion IS satisfiable → still a slot.
        let sized = vec![
            iter_bound("IntoIterator", primitive("i64")),
            trait_bound("Sized", vec![]),
        ];
        assert!(iterator_bound_of(&sized).is_some());
        // A lifetime/outlives companion (no trait name) is satisfiable → slot.
        let lt = vec![
            iter_bound("IntoIterator", primitive("i64")),
            serde_json::json!({ "outlives": "'static" }),
        ];
        assert!(iterator_bound_of(&lt).is_some());
    }

    #[test]
    fn classify_iterator_param_emits_vec_item_and_kind() {
        // [C3] classify resolves Item= through the PARAM-IDX-AWARE resolver and
        // returns (kind, item_typeref). The caller wraps it in `Vec<item>`.
        let bound = iter_bound("IntoIterator", primitive("i64"));
        let (kind, item) =
            classify_iterator_param(IterKind::IntoIter, &bound, &HashMap::new(), true)
                .expect("IntoIterator<Item=i64> classifies");
        assert_eq!(kind, IterKind::IntoIter);
        assert_eq!(item, TypeRef::Prim("i64".into()));

        // Iterator kind preserved.
        let it = iter_bound("Iterator", primitive("i64"));
        let (k2, _) = classify_iterator_param(IterKind::Iter, &it, &HashMap::new(), true)
            .expect("Iterator<Item=i64> classifies");
        assert_eq!(k2, IterKind::Iter);
    }

    #[test]
    fn classify_iterator_param_item_is_param_aware() {
        // [C3] `Item=T` where T is a stub param resolves to TRParam, NOT a String
        // fallback. param_idx maps T→0.
        let param_idx: HashMap<String, usize> = [("T".to_string(), 0usize)].into_iter().collect();
        let bound = iter_bound("IntoIterator", gnode("T"));
        let (_, item) = classify_iterator_param(IterKind::IntoIter, &bound, &param_idx, true)
            .expect("IntoIterator<Item=T> with T a stub param classifies");
        assert_eq!(item, TypeRef::Param(0));
    }

    #[test]
    fn classify_iterator_param_nonrust_abi_drops() {
        // [C8] a non-Rust-ABI host records iterator-nonrust-abi.
        let bound = iter_bound("IntoIterator", primitive("i64"));
        match classify_iterator_param(IterKind::IntoIter, &bound, &HashMap::new(), false) {
            Err(GenericDrop::IteratorDrop(tag, _)) => assert_eq!(tag.tag(), "iterator-nonrust-abi"),
            other => panic!("expected iterator-nonrust-abi drop, got {other:?}"),
        }
    }

    /// A static assoc fn `fn f<I: <trait><Item=i64>>(xs: I) -> i64` on `Foo`.
    fn iter_assoc_fn(bound: serde_json::Value) -> serde_json::Value {
        serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [ type_param("I", vec![bound]) ], "where_predicates": [] },
            "sig": { "inputs": [ ["xs", gnode("I")] ], "output": primitive("i64") }
        })
    }

    #[test]
    fn parametric_stub_into_iterator_param_emits_vec_direct() {
        // `sum_all<I: IntoIterator<Item=i64>>(xs: I) -> i64` binds: I is CONSUMED
        // (no tyvar), the arg is `Vec<i64>`, no into_iter adapter (direct).
        let fd = iter_assoc_fn(iter_bound("IntoIterator", primitive("i64")));
        let stub = try_parametric_stub(
            "sum_all",
            &fd,
            Some(("Foo", "::iter::Foo")),
            None,
            None,
            None,
        )
        .expect("IntoIterator param must bind");
        assert!(stub.params.is_empty(), "I is consumed → no Ipe tyvar");
        assert!(
            stub.bounds.is_empty(),
            "no iterator bound survives as a Ipe bound"
        );
        assert_eq!(
            stub.call.arg_types,
            vec![TypeRef::Ctor(
                "::Vec".into(),
                vec![TypeRef::Prim("i64".into())]
            )]
        );
        assert!(
            stub.call.iter_adapters.is_empty(),
            "IntoIterator is direct (no .into_iter())"
        );
        assert_eq!(stub.call.ret, TypeRef::Prim("i64".into()));
    }

    #[test]
    fn parametric_stub_iterator_param_records_into_iter_adapter() {
        // `count<I: Iterator<Item=i64>>(it: I) -> i64` binds: arg is `Vec<i64>`,
        // and the call form needs `.into_iter()` → adapter at arg index 0 (C6).
        let fd = iter_assoc_fn(iter_bound("Iterator", primitive("i64")));
        let stub =
            try_parametric_stub("count", &fd, Some(("Foo", "::iter::Foo")), None, None, None)
                .expect("Iterator param must bind");
        assert!(stub.params.is_empty());
        assert_eq!(
            stub.call.arg_types,
            vec![TypeRef::Ctor(
                "::Vec".into(),
                vec![TypeRef::Prim("i64".into())]
            )]
        );
        assert_eq!(
            stub.call.iter_adapters,
            vec![0],
            "Iterator arg needs .into_iter()"
        );
    }

    #[test]
    fn parametric_stub_shared_iterator_tyvar_routes_both_slots() {
        // [C1] `zip(a: I, b: I)` — ONE shared iterator tyvar I across two params.
        // The name-keyed consume routes BOTH slots → both emit `Vec<i64>`, no
        // surviving tyvar.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("I", vec![iter_bound("IntoIterator", primitive("i64"))]),
            ], "where_predicates": [] },
            "sig": { "inputs": [
                ["a", gnode("I")],
                ["b", gnode("I")]
            ], "output": primitive("i64") }
        });
        let stub = try_parametric_stub(
            "zip_sum",
            &fd,
            Some(("Foo", "::iter::Foo")),
            None,
            None,
            None,
        )
        .expect("shared iterator tyvar must bind both slots");
        assert!(
            stub.params.is_empty(),
            "the shared I is consumed in BOTH slots"
        );
        let vec_i64 = TypeRef::Ctor("::Vec".into(), vec![TypeRef::Prim("i64".into())]);
        assert_eq!(stub.call.arg_types, vec![vec_i64.clone(), vec_i64]);
    }

    #[test]
    fn parametric_stub_mut_ref_iterator_param_drops() {
        // [C4] a `&mut I` iterator param is NOT a bare `{generic:I}` node → it
        // does NOT match the consume filter → falls to type_to_typeref → drop
        // (a borrowed-ref is outside the bindable owned-monomorphic subset). We
        // must NOT add a borrowed-ref-unwrapping branch.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("I", vec![iter_bound("Iterator", primitive("i64"))]),
            ], "where_predicates": [] },
            "sig": { "inputs": [
                ["it", mut_ref(gnode("I"))]
            ], "output": primitive("i64") }
        });
        match try_parametric_stub("drain", &fd, Some(("Foo", "::iter::Foo")), None, None, None) {
            Err(GenericDrop::NotBindable(_)) => {}
            other => panic!("expected a NotBindable drop for &mut I, got {other:?}"),
        }
    }

    #[test]
    fn parametric_stub_iterator_item_ord_predicate_drops() {
        // [C5] `where I::Item: Ord` is a NON-generic predicate (an assoc-type
        // projection subject) → the full_union_bounds C2 gate drops it. Over-drop
        // is acceptable; under-bind is forbidden.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("I", vec![iter_bound("Iterator", primitive("i64"))]),
            ], "where_predicates": [
                { "bound_predicate": {
                    "type": { "qualified_path": {
                        "name": "Item",
                        "self_type": { "generic": "I" },
                        "trait": { "path": "Iterator", "name": "Iterator", "id": 0, "args": null }
                    } },
                    "bounds": [ trait_bound("Ord", vec![]) ]
                } }
            ] },
            "sig": { "inputs": [ ["it", gnode("I")] ], "output": primitive("i64") }
        });
        assert!(
            try_parametric_stub(
                "sorted",
                &fd,
                Some(("Foo", "::iter::Foo")),
                None,
                None,
                None
            )
            .is_err(),
            "where I::Item: Ord must DROP (non-generic predicate)"
        );
    }

    #[test]
    fn parametric_stub_iterator_tyvar_reused_in_return_drops() {
        // [C2] a consumed iterator tyvar reused in the RETURN (`-> I`) must DROP.
        // I is consumed (no param_idx entry) → type_to_typeref on the `-> I`
        // output hits the free-type-var arm → NotBindable.
        let fd = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [
                type_param("I", vec![iter_bound("IntoIterator", primitive("i64"))]),
            ], "where_predicates": [] },
            "sig": { "inputs": [ ["xs", gnode("I")] ], "output": gnode("I") }
        });
        match try_parametric_stub("ident", &fd, Some(("Foo", "::iter::Foo")), None, None, None) {
            Err(GenericDrop::NotBindable(m)) => assert!(m.contains("free type-var")),
            other => panic!("expected free-type-var NotBindable drop for -> I, got {other:?}"),
        }
    }

    #[test]
    fn parametric_stub_iterator_item_unmodellable_drops() {
        // [C3] an `Item=` that resolves to a non-closed shape (a tuple here) →
        // iterator-item-unmodellable drop (type_to_typeref refuses it).
        let fd = iter_assoc_fn(serde_json::json!({ "trait_bound": { "trait": {
            "path": "IntoIterator", "name": "IntoIterator", "id": 0,
            "args": { "angle_bracketed": { "args": [], "constraints": [
                { "name": "Item", "binding": { "equality": { "type":
                    { "tuple": [ primitive("i64"), primitive("i64") ] } } } }
            ] } }
        }, "modifier": "none" } }));
        match try_parametric_stub("sink", &fd, Some(("Foo", "::iter::Foo")), None, None, None) {
            Err(GenericDrop::IteratorDrop(tag, _)) => {
                assert_eq!(tag.tag(), "iterator-item-unmodellable");
            }
            other => panic!("expected iterator-item-unmodellable drop, got {other:?}"),
        }
    }

    #[test]
    fn test_safe_crate_name() {
        // #6: only [A-Za-z0-9_-]; reject path-traversal / NUL / empty.
        assert_eq!(safe_crate_name("indexmap"), Some("indexmap"));
        assert_eq!(safe_crate_name("serde_json"), Some("serde_json"));
        assert_eq!(safe_crate_name("foo-bar"), Some("foo-bar"));
        assert_eq!(safe_crate_name("../etc/passwd"), None);
        assert_eq!(safe_crate_name("a/b"), None);
        assert_eq!(safe_crate_name("a\0b"), None);
        assert_eq!(safe_crate_name(""), None);
    }

    #[test]
    fn test_generic_serde_shape() {
        // The emitted `generic` JSON must match the wire keys the generator
        // FromJSON reads (drift 4b — Rust emission side).
        let g = Generic {
            params: vec!["K".into(), "V".into()],
            bounds: [("K".to_string(), vec!["Hash".to_string()])]
                .into_iter()
                .collect(),
            call: Call {
                kind: "function".into(),
                path: vec!["::c".into(), "T".into()],
                type_args: vec![TypeRef::Param(0)],
                method: Some("make".into()),
                receiver: None,
                args: vec![0],
                arg_types: vec![TypeRef::Param(0)],
                ret: TypeRef::Ctor("::c::T".into(), vec![TypeRef::Param(0)]),
                iter_adapters: vec![],
                borrow_as_ref_args: vec![],
                trait_qualifier: None,
                is_async: false,
                method_turbofish: vec![],
            },
            mono_resolved: false,
        };
        let v = serde_json::to_value(&g).unwrap();
        assert_eq!(v["params"], serde_json::json!(["K", "V"]));
        assert_eq!(v["call"]["kind"], "function");
        assert_eq!(v["call"]["typeArgs"], serde_json::json!([{ "param": 0 }]));
        assert_eq!(v["call"]["argTypes"], serde_json::json!([{ "param": 0 }]));
        assert_eq!(
            v["call"]["ret"],
            serde_json::json!({ "ctor": "::c::T", "args": [{ "param": 0 }] })
        );
        // a function call must NOT serialise a receiver key.
        assert!(v["call"].get("receiver").is_none());
        // #21 constraint 9: a non-trait Call (trait_qualifier=None) MUST NOT
        // serialise a `traitQualifier` key — byte-identical to a pre-#21 stub.
        assert!(v["call"].get("traitQualifier").is_none());
        // #72: an EMPTY method_turbofish MUST NOT serialise a `methodTurbofish`
        // key — byte-identical to a pre-#72 stub (the legacy single-serde path).
        assert!(v["call"].get("methodTurbofish").is_none());
    }

    #[test]
    fn test_method_turbofish_wire_shape() {
        // #72: a method with TWO own generics, each reduced by a DIFFERENT
        // mechanism (T serde→Value, S AsRef→String), must serialise the ordered
        // `methodTurbofish` list the generator renderer reads — a concrete PER
        // generic in declaration order. The firestore `get_obj<T: DeserializeOwned,
        // S: AsRef<str>>` shape.
        let call = Call {
            kind: "method".into(),
            path: vec!["::c".into(), "Db".into()],
            type_args: vec![],
            method: Some("get_obj".into()),
            receiver: Some(Receiver {
                arg: 0,
                by: "ref".into(),
            }),
            args: vec![1],
            arg_types: vec![
                TypeRef::Ctor("::c::Db".into(), vec![]),
                TypeRef::Prim("String".into()),
            ],
            ret: TypeRef::Ctor(
                "::core::result::Result".into(),
                vec![TypeRef::SerdeValue, TypeRef::Prim("String".into())],
            ),
            iter_adapters: vec![],
            borrow_as_ref_args: vec![],
            trait_qualifier: Some(("::c::Db".into(), "::c::Repo".into())),
            is_async: true,
            // T → serde_json::Value (serdeValue), S → String (prim).
            method_turbofish: vec![TypeRef::SerdeValue, TypeRef::Prim("String".into())],
        };
        let v = serde_json::to_value(&call).unwrap();
        assert_eq!(
            v["methodTurbofish"],
            serde_json::json!([{ "serdeValue": true }, { "prim": "String" }])
        );
    }

    // ── Phase 5: closure-param metadata ────────────────────────────────

    /// A rustdoc `trait_bound` carrying the `Fn(A) -> R` parenthesized sugar.
    /// `inputs` are rustdoc type nodes; `output` is `Some(node)` or `None` (→ `()`).
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn closure_bound(
        trait_name: &str,
        inputs: Vec<serde_json::Value>,
        output: Option<serde_json::Value>,
    ) -> serde_json::Value {
        serde_json::json!({ "trait_bound": { "trait": {
            "path": trait_name, "name": trait_name, "id": 0,
            "args": { "parenthesized": { "inputs": inputs, "output": output } }
        }, "modifier": "none" } })
    }

    /// `&A` (shared borrow) and `&mut A` rustdoc nodes for closure inputs.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn shared_ref(inner: serde_json::Value) -> serde_json::Value {
        serde_json::json!({ "borrowed_ref": { "lifetime": null, "is_mutable": false, "type_": inner } })
    }
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn mut_ref(inner: serde_json::Value) -> serde_json::Value {
        serde_json::json!({ "borrowed_ref": { "lifetime": null, "is_mutable": true, "type_": inner } })
    }

    /// `param_idx` map mirroring `{a:0, b:1}` (the hand-stub closures' tyvars).
    fn ab_idx() -> HashMap<String, usize> {
        [("a".to_string(), 0usize), ("b".to_string(), 1usize)]
            .into_iter()
            .collect()
    }

    #[test]
    fn closure_param_emits_closure_argtype() {
        // A by-ref `Fn(&a) -> bool` bound (the `keep` shape). byRef=true, kind=Fn.
        let bound = closure_bound("Fn", vec![shared_ref(gnode("a"))], Some(prim("bool")));
        let tr = classify_closure_param(&bound, &ab_idx(), true)
            .expect("a by-ref Fn(&a)->bool must classify");
        let v = serde_json::to_value(&tr).unwrap();
        assert_eq!(v["closure"]["kind"], "Fn");
        assert_eq!(v["closure"]["byRef"], true);
        assert_eq!(
            v["closure"]["argTypes"],
            serde_json::json!([{ "param": 0 }])
        );
        assert_eq!(v["closure"]["ret"], serde_json::json!({ "prim": "bool" }));
    }

    #[test]
    fn closure_param_by_value_fn() {
        // `Fn(a) -> b` (the `map_each` shape) — by-value, byRef=false.
        let bound = closure_bound("Fn", vec![gnode("a")], Some(gnode("b")));
        let tr = classify_closure_param(&bound, &ab_idx(), true).expect("Fn(a)->b classifies");
        let v = serde_json::to_value(&tr).unwrap();
        assert_eq!(v["closure"]["kind"], "Fn");
        assert_eq!(v["closure"]["byRef"], false);
        assert_eq!(
            v["closure"]["argTypes"],
            serde_json::json!([{ "param": 0 }])
        );
        assert_eq!(v["closure"]["ret"], serde_json::json!({ "param": 1 }));
    }

    #[test]
    fn closure_param_fnonce_zero_arg() {
        // `FnOnce() -> a` (the `run_once` shape) — no inputs, ret = param 0.
        let bound = closure_bound("FnOnce", vec![], Some(gnode("a")));
        let tr = classify_closure_param(&bound, &ab_idx(), true).expect("FnOnce()->a classifies");
        let v = serde_json::to_value(&tr).unwrap();
        assert_eq!(v["closure"]["kind"], "FnOnce");
        assert_eq!(v["closure"]["byRef"], false);
        assert_eq!(v["closure"]["argTypes"], serde_json::json!([]));
        assert_eq!(v["closure"]["ret"], serde_json::json!({ "param": 0 }));
    }

    #[test]
    fn closure_matches_hand_stub_key_order() {
        // The emitted JSON must carry EXACTLY {kind, byRef, argTypes, ret} under a
        // single `closure` key — the shape the generator `FromJSON TypeRef` reads
        // and the hand-stub `clo.kernel.json` carries.
        let bound = closure_bound("Fn", vec![gnode("a")], Some(prim("bool")));
        let tr = classify_closure_param(&bound, &ab_idx(), true).unwrap();
        let v = serde_json::to_value(&tr).unwrap();
        let inner = v
            .get("closure")
            .and_then(|c| c.as_object())
            .expect("closure object");
        let mut keys: Vec<&String> = inner.keys().collect();
        keys.sort();
        assert_eq!(keys, vec!["argTypes", "byRef", "kind", "ret"]);
        // exactly one top-level discriminator
        assert_eq!(v.as_object().unwrap().len(), 1);
    }

    #[test]
    fn host_abi_rust_reader() {
        // The B3 host-ABI reader: `"Rust"` / absent ⇒ Rust; an `extern "C"` ABI
        // object ⇒ non-Rust. This is the value a caller threads into
        // `classify_closure_param`'s `host_abi_rust` gate.
        let rust = serde_json::json!({ "header": { "abi": "Rust" } });
        assert!(host_abi_is_rust(&rust));
        let absent = serde_json::json!({ "header": { "is_async": false } });
        assert!(host_abi_is_rust(&absent)); // missing abi → assume Rust
        let c = serde_json::json!({ "header": { "abi": { "C": { "unwind": false } } } });
        assert!(!host_abi_is_rust(&c));
        let c_str = serde_json::json!({ "header": { "abi": "C" } });
        assert!(!host_abi_is_rust(&c_str));
    }

    // ── Phase 5.2: coverage drop tags ──────────────────────────────────

    #[test]
    fn closure_drop_nonrust_abi() {
        // B3: a non-Rust-ABI host records the specific `closure-nonrust-abi` tag.
        let bound = closure_bound("Fn", vec![gnode("a")], Some(prim("bool")));
        match classify_closure_param(&bound, &ab_idx(), false) {
            Err(GenericDrop::ClosureDrop(tag, _)) => assert_eq!(tag.tag(), "closure-nonrust-abi"),
            other => panic!("expected closure-nonrust-abi drop, got {other:?}"),
        }
    }

    #[test]
    fn closure_drop_mut_slot() {
        // `Fn(&mut a)` ⇒ closure-mut-slot.
        let bound = closure_bound("Fn", vec![mut_ref(gnode("a"))], Some(prim("bool")));
        match classify_closure_param(&bound, &ab_idx(), true) {
            Err(GenericDrop::ClosureDrop(tag, _)) => assert_eq!(tag.tag(), "closure-mut-slot"),
            other => panic!("expected closure-mut-slot drop, got {other:?}"),
        }
    }

    #[test]
    fn closure_drop_ho_return() {
        // A closure RETURNING a closure ⇒ closure-ho-return. rustdoc models
        // `-> impl Fn(..)` as an impl_trait output, which type_to_typeref can't
        // resolve to the closed set, so it surfaces as a NotBindable BEFORE the
        // ho-return check — that drop is still correct (a higher-order return is
        // never emitted as a closure argType). The DEDICATED ho-return tag fires
        // when the output resolves to a closure TypeRef; assert the taxonomy
        // entry exists and the drop happens.
        assert_eq!(ClosureDropTag::HoReturn.tag(), "closure-ho-return");
        let output = serde_json::json!({ "impl_trait": [
            closure_bound("Fn", vec![gnode("b")], Some(gnode("b")))
        ] });
        let bound = closure_bound("Fn", vec![gnode("a")], Some(output));
        assert!(
            classify_closure_param(&bound, &ab_idx(), true).is_err(),
            "a closure returning a closure must DROP"
        );
    }

    #[test]
    fn closure_drop_by_ref_noclone() {
        // A by-ref closure whose borrowed element is a concrete non-Clone type ⇒
        // closure-by-ref-noclone. A bare opaque ctor `::Foo` (no args) IS treated
        // as Clone-by-vacuous-args, so use a borrowed Vec<closure> — but
        // type_to_typeref can't emit a nested closure. Drive the gate directly
        // through its Clone oracle + assert the tag, and exercise the drop with a
        // borrowed element type_to_typeref CAN resolve to a non-Clone TypeRef:
        // there is no such closed-set concrete (every closed primitive/ctor IS
        // Clone), so the gate is reached only via a nested closure — covered by
        // the oracle assertions below.
        assert_eq!(ClosureDropTag::ByRefNoClone.tag(), "closure-by-ref-noclone");
        let clo = TypeRef::Closure {
            kind: ClosureKind::Fn,
            by_ref: false,
            arg_types: vec![TypeRef::Param(0)],
            ret: Box::new(TypeRef::Prim("bool".into())),
        };
        assert!(!typeref_is_clone(&clo));
        assert!(!typeref_is_clone(&TypeRef::Ctor("::Vec".into(), vec![clo])));
        assert!(typeref_is_clone(&TypeRef::Param(0)));
        assert!(typeref_is_clone(&TypeRef::Prim("String".into())));
        assert!(typeref_is_clone(&TypeRef::Prim("i64".into())));
    }

    #[test]
    fn closure_drop_tags_are_distinct_and_stable() {
        // The five Phase-5.2 tags are distinct stable strings (parity with the
        // generator `closureDropReason` taxonomy + the two inspector-only tags).
        let tags = [
            ClosureDropTag::MutSlot.tag(),
            ClosureDropTag::HoReturn.tag(),
            ClosureDropTag::ByRefNoClone.tag(),
            ClosureDropTag::NonRustAbi.tag(),
            ClosureDropTag::IndirectNoAnalysis.tag(),
        ];
        let mut sorted = tags.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), 5, "all five closure tags must be distinct");
        assert_eq!(
            tags,
            [
                "closure-mut-slot",
                "closure-ho-return",
                "closure-by-ref-noclone",
                "closure-nonrust-abi",
                "closure-indirect-noanalysis",
            ]
        );
        // A ClosureDrop flows its tag through GenericDrop::reason() (the coverage
        // taxonomy emission), so emit_generic_coverage histograms it correctly.
        let d = GenericDrop::ClosureDrop(ClosureDropTag::MutSlot, "x".into());
        assert_eq!(d.reason(), "closure-mut-slot");
        assert_eq!(d.detail(), "x");
    }

    // ── #21 trait methods on concrete types ─────────────────────────────

    /// A `for`-Self rustdoc node carrying a free type-var nested in its args,
    /// e.g. `Vec<T>`.
    fn vec_of_generic(name: &str) -> serde_json::Value {
        serde_json::json!({
            "resolved_path": {
                "name": "Vec", "path": "Vec", "id": 7,
                "args": { "angle_bracketed": {
                    "args": [ { "type": { "generic": name } } ], "constraints": []
                } }
            }
        })
    }

    #[test]
    fn test_self_is_concrete_named() {
        // Concrete BARE named type (no type-args) → concrete.
        assert!(self_is_concrete_named(&path("Circle")));
        // A MONOMORPHIC instantiation of a generic struct (`Pair<i64>`) carries
        // NO free tyvar but IS parametric — the receiver-base strip would drop
        // its `<i64>` (→ E0107 cargo-fail). v1 over-drops it (guardian-final fix).
        assert!(!self_is_concrete_named(&path_with_args(
            "Pair",
            vec![prim("i64")]
        )));
        // A nested concrete instantiation (`Pair<Vec<i64>>`) likewise drops.
        assert!(!self_is_concrete_named(&path_with_args(
            "Pair",
            vec![path_with_args("Vec", vec![prim("i64")])]
        )));
        // A blanket `impl<T> Foo for T` — the Self IS the bare type-var.
        assert!(!self_is_concrete_named(
            &serde_json::json!({ "generic": "T" })
        ));
        // `impl<T> Foo for Vec<T>` — a free type-var nested in args.
        assert!(!self_is_concrete_named(&vec_of_generic("T")));
        // A non-path Self (slice / tuple) is not a concrete named type.
        assert!(!self_is_concrete_named(&prim("i64")));
    }

    /// Build a tiny rustdoc index for a `trait Scale { fn scaled<T: Into<f64>>(…) }`
    /// plus the trait item, returning (index, `trait_node_for_impl`). The impl-side
    /// trait node carries `id` pointing at the trait item.
    fn scale_trait_index() -> (
        serde_json::Map<String, serde_json::Value>,
        serde_json::Value,
    ) {
        let into_f64 = trait_bound("Into", vec![prim("f64")]);
        // The trait-DEF method `scaled<T: Into<f64>>(&self, k: T) -> f64`.
        let scaled_fn = serde_json::json!({
            "name": "scaled",
            "inner": { "function": {
                "generics": { "params": [ type_param("T", vec![into_f64]) ],
                              "where_predicates": [] },
                "sig": { "inputs": [], "output": { "primitive": "f64" } }
            } }
        });
        // The trait item, listing `scaled` as a member by id "100".
        let trait_item = serde_json::json!({
            "name": "Scale", "crate_id": 0,
            "inner": { "trait": { "items": [ 100 ] } }
        });
        let mut index = serde_json::Map::new();
        index.insert("100".to_string(), scaled_fn);
        index.insert("42".to_string(), trait_item);
        // The impl-side trait node references the trait by id 42.
        let trait_node = serde_json::json!({ "id": 42, "name": "Scale", "path": "Scale" });
        (index, trait_node)
    }

    /// A trait-impl method `fn keyed<T>(&self, k: T) -> i64` whose `<T>` is
    /// RESTATED BARE on the impl (the bound `T: Ord` lives on the trait DEF,
    /// modelled here as not inlined onto the impl-method sig). `Ord` is a
    /// modellable-5 trait, so the Q2-A union lets the stub EMIT `<T: Ord>` and
    /// BIND — a row that binds ONLY because it unioned trait-def info
    /// (constraint 12). (An `Into<f64>`-style *resolve-to-concrete* bound would
    /// instead need the `resolve_generics` monomorphisation path, which
    /// `try_parametric_stub` does not run — so `Into`-bare-restate stays a
    /// `trait-method-bound-cross-impl` drop, the sound over-drop.)
    fn keyed_impl_method_bare_t() -> serde_json::Value {
        serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            // BARE `<T>` — no bounds at the impl site.
            "generics": { "params": [ type_param("T", vec![]) ], "where_predicates": [] },
            "sig": { "inputs": [
                ["self", borrowed(serde_json::json!({ "generic": "Self" }))],
                ["k", serde_json::json!({ "generic": "T" })]
            ], "output": prim("i64") }
        })
    }

    /// A `TraitCtx` whose qualifier is fixed and whose trait-def generics are
    /// supplied by the caller (so a test can toggle the Q2-A union on/off).
    fn trait_ctx_with(trait_def: Option<&serde_json::Value>) -> TraitCtx<'_> {
        TraitCtx {
            trait_def_generics: trait_def,
            qualifier: ("::tm::Circle".to_string(), "::tm::Scale".to_string()),
            assoc_bindings: std::collections::HashMap::new(),
        }
    }

    /// A `TraitCtx` carrying concrete assoc-type bindings (constraint 6 tests).
    fn trait_ctx_assoc<'a>(binds: &[(&str, serde_json::Value)]) -> TraitCtx<'a> {
        TraitCtx {
            trait_def_generics: None,
            qualifier: ("::tm::Circle".to_string(), "::tm::Pair".to_string()),
            assoc_bindings: binds
                .iter()
                .map(|(k, v)| (k.to_string(), v.clone()))
                .collect(),
        }
    }

    #[test]
    fn test_q2a_bare_restated_bound_pre_drops_post_binds() {
        // CONSTRAINT-12 REGRESSION — the row that sinks the naive design.
        let fd = keyed_impl_method_bare_t();

        // ── PRE (Q2-A OFF): the trait-def union is absent. The impl-method `<T>`
        //    has EMPTY bounds, so the spec-as-written would emit a bare `<T>`
        //    (→ E0277 at the host call). The Q2-A backstop instead DROPS
        //    `trait-method-bound-cross-impl` — sound (never an unsound emit).
        let pre = try_parametric_stub(
            "keyed",
            &fd,
            Some(("Circle", "::tm::Circle")),
            None,
            None,
            Some(&trait_ctx_with(None)),
        );
        match pre {
            Err(GenericDrop::TraitMethodDrop(TraitMethodDropTag::BoundCrossImpl, _)) => {}
            other => panic!(
                "PRE (no trait-def union): a bare-restated `<T>` MUST drop \
                 trait-method-bound-cross-impl (never emit `<T>`), got {other:?}"
            ),
        }

        // ── POST (Q2-A ON): union the trait-DEF method's `T: Ord` bound. `Ord` is
        //    a modellable-5 trait, so `T` stays a Ipe tyvar and the stub EMITS
        //    `<T: Ord>` — the method BINDS solely because of the union.
        let ord = trait_bound("Ord", vec![]);
        let trait_def = fn_with_generics(vec![type_param("T", vec![ord])], vec![]);
        let post = try_parametric_stub(
            "keyed",
            &fd,
            Some(("Circle", "::tm::Circle")),
            None,
            None,
            Some(&trait_ctx_with(Some(&trait_def["generics"]))),
        );
        let stub = post.expect("POST (trait-def union): `T: Ord` resolves → `keyed` must BIND");
        // T survives as a Ipe tyvar carrying the unioned `Ord` bound.
        assert_eq!(stub.params, vec!["T".to_string()]);
        assert_eq!(stub.bounds.get("T"), Some(&vec!["Ord".to_string()]));
        // The UFCS qualifier rode through onto the Call.
        assert_eq!(
            stub.call.trait_qualifier,
            Some(("::tm::Circle".to_string(), "::tm::Scale".to_string()))
        );
        // The receiver is borrowed (`&self`) — UFCS first-arg by ref.
        assert_eq!(
            stub.call.receiver.as_ref().map(|r| r.by.as_str()),
            Some("ref")
        );
    }

