    #[test]
    fn test_generic_method_on_nongeneric_struct_recv_has_no_method_tyvar() {
        // [C-4 codegen] A GENERIC method (`scaled_by<T: Ord>`) on a NON-generic
        // struct (`Circle`) must render the receiver as the BARE `::tm::Circle`,
        // NOT `::tm::Circle<T>`. The method tyvar `T` belongs in the args/ret, NOT
        // the receiver type — `Circle` takes no type params, so `Circle<T>` is
        // E0107 (wrong number of type arguments). The receiver ctor must carry
        // ONLY the STRUCT's generics (here: none), never the method's.
        let into_ord = trait_bound("Ord", vec![]);
        let scaled = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
            "generics": { "params": [ type_param("T", vec![into_ord]) ],
                          "where_predicates": [] },
            "sig": { "inputs": [
                ["self", borrowed(serde_json::json!({ "generic": "Self" }))],
                ["k", serde_json::json!({ "generic": "T" })],
                ["floor", serde_json::json!({ "generic": "T" })]
            ], "output": prim("f64") }
        });
        // struct_generics = NONE (Circle is non-generic). trait_ctx with the
        // qualifier so it routes as a trait method (the real scaled_by shape).
        let trait_def = fn_with_generics(
            vec![type_param("T", vec![trait_bound("Ord", vec![])])],
            vec![],
        );
        let stub = try_parametric_stub(
            "scaled_by",
            &scaled,
            Some(("Circle", "::tm::Circle")),
            None,
            /* impl_generics */ None, /* struct_generics: NON-generic */
            Some(&trait_ctx_with(Some(&trait_def["generics"]))),
        )
        .expect("scaled_by<T: Ord> on non-generic Circle binds");
        // The receiver (arg_types[0]) must be a BARE ctor — no `T` arg.
        match stub.call.arg_types.first() {
            Some(TypeRef::Ctor(p, args)) => {
                assert_eq!(p, "::tm::Circle");
                assert!(
                    args.is_empty(),
                    "receiver Circle (non-generic struct) must carry NO type args; \
                     a method tyvar `<T>` in the receiver is E0107. got {args:?}"
                );
            }
            other => panic!("expected a receiver ctor, got {other:?}"),
        }
        // `T` still appears as a Ipe tyvar (in the value args), just not the recv.
        assert_eq!(stub.params, vec!["T".to_string()]);
    }

    #[test]
    fn test_trait_method_parametric_fn_leaves_recv_empty() {
        // [C-4 codegen] A TRAIT-method parametric stub MUST leave `recv_type` /
        // `method_name` EMPTY so the Ipe compiler routes it ONLY through the
        // generic-wrapper synthesiser (UFCS `<Self as Trait>::m`) and does NOT
        // ALSO emit an INHERENT `arg0.m()` duplicate via the non-generic path.
        // A set `recv_type` triggers BOTH paths → a duplicate wrapper (E0659
        // ambiguity) whose inherent body is an E0599 (a trait method isn't
        // callable inherently). The receiver lives in `generic.call.receiver` +
        // `argTypes`, so synthesiseGenericWrapper needs nothing from recv_type.
        let fd = first_assoc_method(); // `fn first(&self) -> Self::A`, A=i64.
        let ctx = trait_ctx_assoc(&[("A", prim("i64"))]);
        let stub = try_parametric_stub(
            "first",
            &fd,
            Some(("Circle", "::tm::Circle")),
            None,
            None,
            Some(&ctx),
        )
        .expect("assoc Self::A=i64 → binds");
        let f = parametric_function("first", &fd, "Circle", "::tm::Circle", stub)
            .expect("parametric_function builds the trait-method Function");
        // The Function carries the UFCS qualifier in its generic block …
        assert!(
            f.generic
                .as_ref()
                .is_some_and(|g| g.call.trait_qualifier.is_some())
        );
        // … and leaves recv_type / method_name EMPTY (no inherent duplicate).
        assert_eq!(
            f.recv_type, "",
            "a trait method must not set recv_type (inherent dup)"
        );
        assert_eq!(
            f.method_name, "",
            "a trait method must not set method_name (inherent dup)"
        );
    }

    #[test]
    fn test_inherent_generic_method_keeps_recv() {
        // CONTROL: an INHERENT generic method (NO trait qualifier) MUST keep
        // recv_type / method_name set — its wrapper renders the inherent
        // `arg0.method()` form (correct; no UFCS qualifier exists). Only the
        // trait-method case clears them.
        let fd = keyed_impl_method_bare_t(); // `fn keyed<T>(&self, k: T) -> i64`
        let ord = trait_bound("Ord", vec![]);
        let trait_def = fn_with_generics(vec![type_param("T", vec![ord])], vec![]);
        // Inherent: thread a trait ctx with NO qualifier? No — inherent means
        // trait_ctx None. Use None so the stub has trait_qualifier=None.
        let stub =
            try_parametric_stub("keyed", &fd, Some(("Box1", "::cr::Box1")), None, None, None)
                .expect("inherent generic method binds");
        assert!(stub.call.trait_qualifier.is_none());
        let f = parametric_function("keyed", &fd, "Box1", "::cr::Box1", stub)
            .expect("parametric_function builds");
        // recv_type is KEPT non-empty (the inherent path needs it). Its exact
        // value carries the method tyvar (`Box1 t`) — the point is it is NOT
        // cleared, so the inherent `arg0.keyed()` wrapper still renders.
        assert!(!f.recv_type.is_empty(), "inherent method keeps recv_type");
        assert_eq!(f.method_name, "keyed", "inherent method keeps method_name");
        let _ = trait_def; // (kept for shape parity with the trait-def union test)
    }

    /// Build a minimal rustdoc doc: a public crate-root module exporting a
    /// generic struct `Holder<T>`, a trait `Area { fn area(&self) -> f64; }`, and
    /// an `impl Area for Holder<i64>` carrying ONE method `area`. `recv_self` is
    /// the receiver-type JSON of the method's first input (`&self` / `self`).
    /// The `for`-Self is `Holder<i64>` — a MONOMORPHIC instantiation of a generic
    /// struct (carries `<i64>` angle-bracket args → `self_is_concrete_named`
    /// returns false → NON-concrete-Self trait method).
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn holder_i64_area_doc(recv_self: serde_json::Value) -> serde_json::Value {
        // The impl-method `area(&self) -> f64` (NON-generic: no method tyvars).
        // visibility "public" here so the method passes the method-level
        // `is_public` gate independently of Step 3's relaxation — this test
        // isolates the C-3 concrete-Self gate on the trait-routing path, not the
        // visibility relaxation.
        let area_method = serde_json::json!({
            "name": "area", "crate_id": 0, "visibility": "public",
            "inner": { "function": {
                "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
                "generics": { "params": [], "where_predicates": [] },
                "sig": { "inputs": [ ["self", recv_self] ], "output": { "primitive": "f64" } }
            } }
        });
        // The trait `Area` (id 42) with `area` as a member (id 100).
        let area_trait = serde_json::json!({
            "name": "Area", "crate_id": 0, "visibility": "public",
            "inner": { "trait": { "items": [ 100 ] } }
        });
        // Self `Holder<i64>` — resolved_path id 7 WITH angle-bracket `<i64>`.
        let holder_i64 = serde_json::json!({
            "resolved_path": { "name": "Holder", "path": "Holder", "id": 7,
                "args": { "angle_bracketed": {
                    "args": [ { "type": { "primitive": "i64" } } ], "bindings": [] } } }
        });
        // The impl `Area for Holder<i64>` (id 50), listing `area` (id 100).
        let area_impl = serde_json::json!({
            "name": null, "crate_id": 0, "visibility": "default",
            "inner": { "impl": {
                "generics": { "params": [], "where_predicates": [] },
                "trait": { "id": 42, "name": "Area", "path": "Area" },
                "for": holder_i64,
                "items": [ 100 ]
            } }
        });
        // The generic struct `Holder<T>` (id 7).
        let holder_struct = serde_json::json!({
            "name": "Holder", "crate_id": 0, "visibility": "public",
            "inner": { "struct": {
                "kind": "unit",
                "generics": { "params": [ type_param("T", vec![]) ], "where_predicates": [] }
            } }
        });
        // The crate-root module (id 1) exporting struct + trait + impl so
        // REACHABLE_PATHS resolves `tm::Holder` / `tm::Area`.
        let root_mod = serde_json::json!({
            "name": "tm", "crate_id": 0, "visibility": "public",
            "inner": { "module": { "items": [ 7, 42, 50 ], "is_crate": true } }
        });
        serde_json::json!({
            "root": 1,
            "index": {
                "1": root_mod,
                "7": holder_struct,
                "42": area_trait,
                "50": area_impl,
                "100": area_method
            },
            "paths": {
                "1":  { "path": ["tm"],          "kind": "module" },
                "7":  { "path": ["tm","Holder"], "kind": "struct" },
                "42": { "path": ["tm","Area"],   "kind": "trait" }
            }
        })
    }

    /// Build a minimal rustdoc doc: a public crate-root module exporting a
    /// BARE concrete struct `Circle`, a public trait `Area`, and an
    /// `impl Area for Circle` carrying ONE non-generic method `area(&self) -> f64`
    /// whose `visibility` is the caller-supplied value (trait methods carry
    /// `"default"` even when callable). The Self `Circle` is a bare named path
    /// (no angle-bracket args) → `self_is_concrete_named` true → routes through
    /// the parametric/UFCS path.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn circle_area_doc(
        method_vis: &str,
        sig_inputs: serde_json::Value,
        sig_output: serde_json::Value,
    ) -> serde_json::Value {
        let area_method = serde_json::json!({
            "name": "area", "crate_id": 0, "visibility": method_vis,
            "inner": { "function": {
                "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
                "generics": { "params": [], "where_predicates": [] },
                "sig": { "inputs": sig_inputs, "output": sig_output }
            } }
        });
        let area_trait = serde_json::json!({
            "name": "Area", "crate_id": 0, "visibility": "public",
            "inner": { "trait": { "items": [ 100 ] } }
        });
        // Self `Circle` — bare resolved_path id 7, NO angle-bracket args.
        let circle = serde_json::json!({
            "resolved_path": { "name": "Circle", "path": "Circle", "id": 7, "args": null }
        });
        let area_impl = serde_json::json!({
            "name": null, "crate_id": 0, "visibility": "default",
            "inner": { "impl": {
                "generics": { "params": [], "where_predicates": [] },
                "trait": { "id": 42, "name": "Area", "path": "Area" },
                "for": circle,
                "items": [ 100 ]
            } }
        });
        let circle_struct = serde_json::json!({
            "name": "Circle", "crate_id": 0, "visibility": "public",
            "inner": { "struct": {
                "kind": "unit",
                "generics": { "params": [], "where_predicates": [] }
            } }
        });
        // A public free constructor `make_circle() -> Circle` (id 60) so `Circle`
        // is owned-producible → the by-value-receiver Sized gate keeps `area`.
        let make_circle = serde_json::json!({
            "name": "make_circle", "crate_id": 0, "visibility": "public",
            "inner": { "function": {
                "header": { "is_async": false, "is_unsafe": false, "abi": "Rust" },
                "generics": { "params": [], "where_predicates": [] },
                "sig": { "inputs": [], "output": {
                    "resolved_path": { "name": "Circle", "path": "Circle", "id": 7, "args": null } } }
            } }
        });
        let root_mod = serde_json::json!({
            "name": "tm", "crate_id": 0, "visibility": "public",
            "inner": { "module": { "items": [ 7, 42, 50, 60 ], "is_crate": true } }
        });
        serde_json::json!({
            "root": 1,
            "index": {
                "1": root_mod, "7": circle_struct, "42": area_trait,
                "50": area_impl, "100": area_method, "60": make_circle
            },
            "paths": {
                "1":  { "path": ["tm"],          "kind": "module" },
                "7":  { "path": ["tm","Circle"], "kind": "struct" },
                "42": { "path": ["tm","Area"],   "kind": "trait" }
            }
        })
    }

    #[test]
    fn test_default_visibility_trait_method_binds() {
        // [Relaxation / the delivery] A public-trait + public-type method whose
        // item-level `visibility` is `"default"` (the structural value for EVERY
        // trait-impl method) must now BIND — the trait+Self reachability + the
        // per-signature nameability gates carry callability, NOT the method's own
        // visibility. Pre-relaxation this dropped at the `is_public` gate.
        let doc = circle_area_doc(
            "default",
            serde_json::json!([["self", borrowed(serde_json::json!({ "generic": "Self" }))]]),
            serde_json::json!({ "primitive": "f64" }),
        );
        let pkg = parse_rustdoc(&doc, "tm", "0.1.0");
        let area = pkg.functions.iter().find(|f| f.name == "area").expect(
            "a `default`-visibility trait method on a public trait+type \
                     MUST bind after the relaxation",
        );
        // It bound as a trait method → carries the UFCS qualifier.
        let g = area
            .generic
            .as_ref()
            .expect("trait method binds as a parametric stub");
        assert_eq!(
            g.call.trait_qualifier,
            Some(("::tm::Circle".to_string(), "::tm::Area".to_string())),
            "the bound trait method must carry the UFCS qualifier"
        );
    }

    #[test]
    fn test_trait_method_private_type_in_sig_drops() {
        // [Regression] A `default` trait method whose RETURN references a PRIVATE
        // type (`Secret`, absent from REACHABLE_PATHS → renders bare `Secret`)
        // still DROPS via the per-signature nameability gate — no E0603. The
        // relaxation does NOT weaken this gate.
        let mut doc = circle_area_doc(
            "default",
            serde_json::json!([["self", borrowed(serde_json::json!({ "generic": "Self" }))]]),
            // Return a private opaque type by id 8 (crate-local but NOT a public
            // module item → unreachable → renders bare `Secret`).
            serde_json::json!({
                "resolved_path": { "name": "Secret", "path": "Secret", "id": 8, "args": null }
            }),
        );
        // `Secret` is a CRATE-LOCAL struct (crate_id 0) but is NOT listed in any
        // public module's items → absent from REACHABLE_PATHS → unreachable.
        doc["index"]["8"] = serde_json::json!({
            "name": "Secret", "crate_id": 0, "visibility": "default",
            "inner": { "struct": { "kind": "unit",
                "generics": { "params": [], "where_predicates": [] } } }
        });
        let pkg = parse_rustdoc(&doc, "tm", "0.1.0");
        assert!(
            !pkg.functions.iter().any(|f| f.name == "area"),
            "a trait method returning a private/unreachable type must DROP \
             (nameability), even after the visibility relaxation"
        );
    }

    #[test]
    fn test_trait_method_index_stripped_private_return_drops() {
        // [guardian #31 — BLOCKING under-bind] The headline defect. A PUBLIC
        // trait method `reveal(&self) -> Secret` where `Secret` is `pub(crate)`.
        // Default `cargo rustdoc` (no `--document-private-items`) STRIPS `Secret`
        // from the index, so its id (8) is referenced in the signature but ABSENT
        // from `doc["index"]` → never enters LOCAL_TYPE_IDS. The OLD gate
        // (`is_unreachable_local_type` = in-LOCAL_TYPE_IDS && !reachable) returned
        // FALSE → no drop → the parametric path fell to the bare last-segment
        // `::Secret` → E0603/E0433 cargo-fail. The TOTAL `resolved_path_is_bindable`
        // fallback must DROP it (neither reachable, nor in EXTERNAL_TYPE_IDS, nor
        // always-nameable). This was RED before the fix (the method BOUND today).
        let doc = circle_area_doc(
            "default",
            serde_json::json!([["self", borrowed(serde_json::json!({ "generic": "Self" }))]]),
            serde_json::json!({
                "resolved_path": { "name": "Secret", "path": "Secret", "id": 8, "args": null }
            }),
        );
        // CRITICAL: id 8 is NOT added to doc["index"] (stripped by default rustdoc)
        // and NOT in doc["paths"] (not a public/external item). It exists ONLY in
        // the signature reference above.
        let pkg = parse_rustdoc(&doc, "tm", "0.1.0");
        assert!(
            !pkg.functions.iter().any(|f| f.name == "area"),
            "a trait method RETURNING an index-stripped pub(crate) type must DROP \
             (no bare ::Secret under-bind)"
        );
    }

    #[test]
    fn test_trait_method_index_stripped_private_param_drops() {
        // [guardian #31] Same defect via a PARAM position: `take(&self, s: Secret)`
        // where `Secret` is index-stripped pub(crate). The param's `type_to_typeref`
        // must drop (the `?` at the value-arg conversion propagates) → no method.
        let doc = circle_area_doc(
            "default",
            serde_json::json!([
                ["self", borrowed(serde_json::json!({ "generic": "Self" }))],
                ["s", { "resolved_path": { "name": "Secret", "path": "Secret", "id": 8, "args": null } }]
            ]),
            serde_json::json!({ "primitive": "f64" }),
        );
        // id 8 deliberately absent from index + paths (stripped).
        let pkg = parse_rustdoc(&doc, "tm", "0.1.0");
        assert!(
            !pkg.functions.iter().any(|f| f.name == "area"),
            "a trait method TAKING an index-stripped pub(crate) type must DROP"
        );
    }

    #[test]
    fn test_generic_trait_method_index_stripped_private_return_drops() {
        // [guardian #31 — headline-delivery path] A GENERIC trait method
        // `gen_reveal<T: Ord>(&self, k: T) -> Secret` returning the index-stripped
        // pub(crate) `Secret`. This is the parametric-stub path where the ret
        // `rust_type` is empty (parse_generic_method_fn) so the downstream
        // `fn_types_nameable` string-gate is blind — the drop MUST come from the
        // `type_to_typeref` total fallback on the `-> Secret` output node.
        let mut doc = circle_area_doc(
            "default",
            serde_json::json!([
                ["self", borrowed(serde_json::json!({ "generic": "Self" }))],
                ["k", { "generic": "T" }]
            ]),
            serde_json::json!({
                "resolved_path": { "name": "Secret", "path": "Secret", "id": 8, "args": null }
            }),
        );
        // Declare the method-level generic `<T: Ord>` on the method node (id 100)
        // so it parses as a generic method (not an undeclared-tyvar drop on `k`).
        doc["index"]["100"]["inner"]["function"]["generics"] = serde_json::json!({
            "params": [ type_param("T", vec![ trait_bound("Ord", vec![]) ]) ],
            "where_predicates": []
        });
        // id 8 (Secret) absent from index + paths (stripped pub(crate)).
        let pkg = parse_rustdoc(&doc, "tm", "0.1.0");
        assert!(
            !pkg.functions.iter().any(|f| f.name == "area"),
            "a GENERIC trait method returning an index-stripped pub(crate) type \
             must DROP (the parametric-path under-bind the guardian reproduced)"
        );
    }

