    #[test]
    fn generic_fn_bound_not_caught_by_dyn_fn_object_drop() {
        // CONTROL: a GENERIC `F: Fn(i64)->i64` param (a `generic` node, NOT a
        // `dyn_trait` object) must NOT be classified as a dyn-Fn-OBJECT drop — it is
        // the closure seam's job (#28). The object-only predicate must return false
        // for the bare type-variable param node.
        let f_param = serde_json::json!({ "generic": "F" });
        assert!(
            !is_dyn_trait_object_including_fn(&f_param),
            "a generic `F` param node must NOT be classified as a dyn-trait OBJECT drop"
        );
        // And the bound carrier (the trait_bound node in generics.params) is not a
        // dyn_trait object either.
        let bound = closure_bound("Fn", vec![gnode("A")], Some(gnode("B")));
        assert!(
            !is_dyn_trait_object_including_fn(&bound),
            "a generic `F: Fn` trait_bound must NOT be a dyn-trait OBJECT drop"
        );
    }

    #[test]
    fn dyn_fn_object_classified_by_inclusive_predicate() {
        // The inclusive predicate DOES catch a `dyn Fn` OBJECT (nested in Box) — the
        // distinction from `is_dyn_trait_object` (which excludes the Fn-family for
        // the closure seam).
        let fn_obj = dyn_fn_object_node("Fn", vec![prim("i64")], prim("i64"));
        assert!(
            is_dyn_trait_object_including_fn(&box_of(fn_obj.clone())),
            "Box<dyn Fn(..)> OBJECT must be caught by the inclusive predicate"
        );
        // And the closure-seam predicate still EXCLUDES it (unchanged contract).
        assert!(
            !is_dyn_trait_object(&box_of(fn_obj)),
            "closure-seam predicate must still EXCLUDE the Fn-family dyn object"
        );
    }

    // ── P1 unit tests: async Send gate (C1) ───────────────────────────────────

    /// Helper: extract the T from `Result<T, E>` as the Send gate does (mirrors
    /// the inline extraction logic in the gate body).
    fn unwrap_result_outer_test(rt: &str) -> &str {
        rt.trim()
            .strip_prefix("Result<")
            .and_then(|s| {
                let bytes = s.as_bytes();
                let mut depth: usize = 0;
                let mut comma_pos: Option<usize> = None;
                for (i, &b) in bytes.iter().enumerate() {
                    match b {
                        b'<' => depth += 1,
                        b'>' => {
                            if depth == 0 {
                                if let Some(cp) = comma_pos {
                                    return Some(s[..cp].trim());
                                }
                                return None;
                            }
                            depth -= 1;
                        }
                        b',' if depth == 0 => {
                            comma_pos = Some(i);
                        }
                        _ => {}
                    }
                }
                None
            })
            .unwrap_or(rt.trim())
    }

    #[test]
    fn async_send_gate_unwrap_result_outer() {
        // Plain Result<T, E> → T
        assert_eq!(unwrap_result_outer_test("Result<i64, String>"), "i64");
        assert_eq!(unwrap_result_outer_test("Result<String, String>"), "String");
        // Nested Result<Vec<i64>, String> → Vec<i64>
        assert_eq!(
            unwrap_result_outer_test("Result<Vec<i64>, String>"),
            "Vec<i64>"
        );
        // NOT a Result → unchanged
        assert_eq!(unwrap_result_outer_test("String"), "String");
        assert_eq!(unwrap_result_outer_test("i64"), "i64");
        assert_eq!(
            unwrap_result_outer_test("asyncffi72::NonSendAux"),
            "asyncffi72::NonSendAux"
        );
    }

    #[test]
    fn async_send_gate_coercible_admits_primitives_and_string() {
        // All primitives and String are admitted by the async-specific Send gate.
        for t in ["i64", "i32", "u64", "f64", "bool", "char", "String"] {
            assert!(
                is_async_send_output(t),
                "primitive {t} must be admitted by async Send gate"
            );
        }
    }

    #[test]
    fn async_send_gate_drops_non_send_output() {
        // A non-Clone opaque output type is NOT in the closed coercible set.
        // This mirrors the `non_send()` → NonSendAux NEGATIVE fixture (72-ffi-async).
        let non_send_types = [
            "asyncffi72::NonSendAux",
            "some_crate::RawPtrHolder",
            "OpaqueStruct",
        ];
        for t in non_send_types {
            assert!(
                !is_async_send_output(t),
                "non-Send opaque {t} must be DROPPED by async Send gate"
            );
            assert!(
                !is_async_send_seq(t),
                "non-Send opaque {t} is not a coercible async sequence"
            );
        }
    }

    #[test]
    fn async_send_gate_drops_clone_but_not_send_output() {
        // `Clone + !Send` structs (e.g. Rc-backed) are admitted by the SYNC gate
        // (`is_ipe_coercible_elem` via `is_clone_opaque_name`) because sync FFI
        // does not need `Send`.  The ASYNC gate (`is_async_send_output`) must DROP
        // them — `tokio::task::spawn` requires `Output: Send + 'static`, and admitting
        // a `!Send` type produces E0277 at cargo build.
        //
        // In the unit test context CLONE_OPAQUE_NAMES is empty (populated at
        // crate-load time from the real rustdoc JSON), so we verify the structural
        // property: `is_ipe_coercible_elem` vs `is_async_send_output` for a plain
        // name that would be a clone-opaque candidate (no `&`, no `<`, no `[`).
        //
        // The key invariant: `is_clone_opaque_name("CloneButNotSend")` would be true
        // in a real run (the struct derives Clone), but `is_async_send_output` never
        // calls `is_clone_opaque_name` — it only admits the 15-item primitive set.
        // Verify the structural branching:
        let clone_not_send = "CloneButNotSend";
        // is_ipe_coercible_elem calls is_clone_opaque_name (empty here → false, but
        // the key point is that even if CLONE_OPAQUE_NAMES were populated, the ASYNC
        // gate would still drop it because is_async_send_output has no clone-opaque arm).
        assert!(
            !is_async_send_output(clone_not_send),
            "a non-primitive opaque ({clone_not_send}) must be DROPPED by async Send gate \
             even if it derives Clone"
        );
        assert!(
            !is_async_send_seq(&format!("Vec<{clone_not_send}>")),
            "Vec<CloneButNotSend> must be DROPPED by async sequence gate"
        );
    }

    #[test]
    fn async_send_gate_fallible_result_strips_to_inner() {
        // `Result<i64, String>` → inner T = `i64` → admitted.
        let inner = unwrap_result_outer_test("Result<i64, String>");
        assert_eq!(inner, "i64");
        assert!(
            is_async_send_output(inner),
            "inner type {inner} of Result<i64,String> must be admitted by async Send gate"
        );

        // `Result<String, String>` → inner T = `String` → admitted.
        let inner2 = unwrap_result_outer_test("Result<String, String>");
        assert_eq!(inner2, "String");
        assert!(is_async_send_output(inner2));

        // `Result<asyncffi72::NonSendAux, String>` → inner T = `asyncffi72::NonSendAux`
        // → not in async-send set → the async gate would drop this function.
        let inner3 = unwrap_result_outer_test("Result<asyncffi72::NonSendAux, String>");
        assert_eq!(inner3, "asyncffi72::NonSendAux");
        assert!(
            !is_async_send_output(inner3),
            "non-Send inner type must NOT be admitted by async Send gate"
        );
    }

    // ── P2 unit test: async Send gate covers ARG types (guardian #44 follow-up) ──
    //
    // An `async fn f(x: RcBacked) -> i64` where `RcBacked` is a crate-local
    // Clone-but-!Send struct MUST be dropped.  Today parse_fn_item checks the
    // OUTPUT type only — so with `i64` as the return type the gate passes and
    // the fn binds.  After the fix, the param-side Send check fires and returns
    // None (tagged `async-future-not-send`).
    //
    // In this unit-test context CLONE_OPAQUE_NAMES is empty, so
    // `is_clone_opaque_name("RcBacked")` returns false.  That means
    // `owned_copy_admissible("&RcBacked")` also returns false, which is the
    // correct structural property: an `Rc`-backed type is not Send regardless
    // of whether the thread-local name set is populated.
    #[test]
    fn async_send_gate_covers_param_types() {
        // Async fn with a non-Send opaque param (owned) and a Send output (i64).
        // MUST be dropped — the async wrapper captures params in `async move { … }`
        // which requires all captured values (including args) to be Send.
        let non_send_param = serde_json::json!({
            "resolved_path": { "name": "RcBacked", "path": "RcBacked", "id": 0, "args": null }
        });
        let fd_owned_param = serde_json::json!({
            "header": { "is_async": true, "is_unsafe": false },
            "generics": { "params": [], "where_predicates": [] },
            "sig": {
                "inputs": [ ["x", non_send_param] ],
                "output": { "primitive": "i64" }
            }
        });
        assert!(
            parse_fn_item("take_non_send", &fd_owned_param, &HashMap::new(), None).is_none(),
            "async fn with a non-Send opaque param MUST be dropped (async-future-not-send)"
        );

        // By-ref non-Send opaque param (`&RcBacked`): the wrapper would call
        // `.to_owned()` on it (owned_copy_admissible path), yielding an owned
        // `RcBacked` that is still `!Send` and still captured by the async move.
        // In this unit-test, CLONE_OPAQUE_NAMES is empty so `owned_copy_admissible`
        // already returns false — but the param-level async Send gate ALSO blocks it.
        let non_send_ref_param = serde_json::json!({
            "borrowed_ref": {
                "lifetime": null,
                "mutable": false,
                "type": { "resolved_path": { "name": "RcBacked", "path": "RcBacked", "id": 0, "args": null } }
            }
        });
        let fd_ref_param = serde_json::json!({
            "header": { "is_async": true, "is_unsafe": false },
            "generics": { "params": [], "where_predicates": [] },
            "sig": {
                "inputs": [ ["x", non_send_ref_param] ],
                "output": { "primitive": "i64" }
            }
        });
        assert!(
            parse_fn_item("take_non_send_ref", &fd_ref_param, &HashMap::new(), None).is_none(),
            "async fn with a &non-Send opaque param MUST be dropped (async-future-not-send)"
        );

        // Control: async fn with only Send params (primitives + String) and a Send
        // return MUST bind.
        let fd_send_params = serde_json::json!({
            "header": { "is_async": true, "is_unsafe": false },
            "generics": { "params": [], "where_predicates": [] },
            "sig": {
                "inputs": [
                    ["n", { "primitive": "i64" }],
                    ["s", { "resolved_path": { "name": "String", "path": "String", "id": 0, "args": null } }]
                ],
                "output": { "primitive": "bool" }
            }
        });
        assert!(
            parse_fn_item("send_async_fn", &fd_send_params, &HashMap::new(), None).is_some(),
            "async fn with Send-only params must still bind"
        );

        // Control: SYNC fn with a non-Send opaque param MUST still bind (no spawn →
        // no Send requirement).
        let non_send_param2 = serde_json::json!({
            "resolved_path": { "name": "RcBacked", "path": "RcBacked", "id": 0, "args": null }
        });
        let fd_sync_non_send = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false },
            "generics": { "params": [], "where_predicates": [] },
            "sig": {
                "inputs": [ ["x", non_send_param2] ],
                "output": { "primitive": "i64" }
            }
        });
        // Sync fns are UNAFFECTED: the param-side async Send gate fires only when
        // effect == "effectful".  A non-Send opaque param is still bindable for
        // sync FFI.  (fn_types_nameable drops it later, outside parse_fn_item, but
        // parse_fn_item itself must return Some here.)
        assert!(
            parse_fn_item("sync_non_send", &fd_sync_non_send, &HashMap::new(), None).is_some(),
            "sync fn with a non-Send opaque param must NOT be affected by the async Send gate"
        );
    }

    // ── DEFECT-1 unit test: async RECEIVER Send gate ─────────────────────────
    //
    // An `async fn m(&self) -> Result<i64, String>` on a `Clone + !Send`
    // (Rc-backed) receiver MUST be dropped: the async wrapper captures the
    // receiver by-MOVE into `async move { arg0.m().await }`, so a !Send receiver
    // → non-Send future → E0277 at `tokio::task::spawn` (type-checks in
    // `ipe dev build`, fails `cargo`). NO non-self params here — the param gate can't
    // catch it; the receiver gate must. A provably-Send receiver still binds; a
    // SYNC method on a !Send receiver is unaffected (no spawn).
    //
    // In this unit-test context PROVABLY_SEND_RECV_NAMES / PROVABLY_SEND_OPAQUE_NAMES
    // are empty, so an opaque receiver name is NOT provably Send → drops. A
    // primitive/String receiver is trivially Send (`is_async_send_output`). To
    // exercise the proven-opaque path we insert a name into the recv-name set.
    #[test]
    fn async_send_gate_covers_receiver() {
        // self input: `&self` (borrowed_ref to the recv type).
        let self_input = serde_json::json!([
            "self",
            { "borrowed_ref": { "lifetime": null, "mutable": false,
              "type": { "resolved_path": { "name": "DbHandle", "path": "DbHandle", "id": 0, "args": null } } } }
        ]);
        // Result<i64, String> output — the Send-Output check unwraps to i64 (Send).
        let fallible_i64 = serde_json::json!({
            "resolved_path": {
                "name": "Result", "path": "Result", "id": 0,
                "args": { "angle_bracketed": { "args": [
                    { "type": { "primitive": "i64" } },
                    { "type": { "resolved_path": { "name": "String", "path": "String", "id": 0, "args": null } } }
                ], "constraints": [] } }
            }
        });
        let async_method = |out: &serde_json::Value| {
            serde_json::json!({
                "header": { "is_async": true, "is_unsafe": false },
                "generics": { "params": [], "where_predicates": [] },
                "sig": { "inputs": [ self_input ], "output": out }
            })
        };

        // (1) RED→GREEN: async instance method on a !Send opaque receiver MUST drop.
        //     Pre-fix this returned Some (self skipped, no recv check) → E0277.
        PROVABLY_SEND_RECV_NAMES.with(|c| c.borrow_mut().clear());
        PROVABLY_SEND_OPAQUE_NAMES.with(|c| c.borrow_mut().clear());
        assert!(
            parse_fn_item(
                "m",
                &async_method(&fallible_i64),
                &HashMap::new(),
                Some(("DbHandle", "DbHandle"))
            )
            .is_none(),
            "async instance method on a !Send receiver MUST be dropped (async-future-not-send)"
        );

        // (2) No over-drop: a PROVEN-Send opaque receiver still binds.
        PROVABLY_SEND_RECV_NAMES.with(|c| {
            c.borrow_mut().insert("SendDb".to_string());
        });
        assert!(
            parse_fn_item(
                "m",
                &async_method(&fallible_i64),
                &HashMap::new(),
                Some(("SendDb", "SendDb"))
            )
            .is_some(),
            "async instance method on a PROVEN-Send receiver must still bind"
        );
        PROVABLY_SEND_RECV_NAMES.with(|c| c.borrow_mut().clear());

        // (3) Control: SYNC method on a !Send receiver is unaffected (no spawn).
        let sync_method = serde_json::json!({
            "header": { "is_async": false, "is_unsafe": false },
            "generics": { "params": [], "where_predicates": [] },
            "sig": { "inputs": [ serde_json::json!([
                "self",
                { "borrowed_ref": { "lifetime": null, "mutable": false,
                  "type": { "resolved_path": { "name": "DbHandle", "path": "DbHandle", "id": 0, "args": null } } } }
            ]) ], "output": { "primitive": "i64" } }
        });
        assert!(
            parse_fn_item(
                "sync_m",
                &sync_method,
                &HashMap::new(),
                Some(("DbHandle", "DbHandle"))
            )
            .is_some(),
            "sync method on a !Send receiver must NOT be affected by the async receiver gate"
        );
    }

    // ── #47(a) serde-bound generic tests ─────────────────────────────────────

    /// Build a minimal serde `trait_bound` node with the given canonical path.
    /// `id` is left at 0 (no `doc["paths"]` loaded in unit tests) so the
    /// fallback last-segment + path check in `is_serde_trait_bound` fires.
    fn serde_bound(canonical_path: &str) -> serde_json::Value {
        let last = canonical_path.rsplit("::").next().unwrap_or(canonical_path);
        serde_json::json!({
            "trait_bound": {
                "trait": {
                    "name": last,
                    "path": canonical_path,
                    "id": { "index": 0, "is_crate_root": false },
                    "args": null
                },
                "generic_params": [],
                "modifier": "none"
            }
        })
    }

    fn marker_bound(name: &str) -> serde_json::Value {
        serde_json::json!({
            "trait_bound": {
                "trait": { "name": name, "path": name, "id": { "index": 0, "is_crate_root": false }, "args": null },
                "generic_params": [],
                "modifier": "none"
            }
        })
    }

    fn generic_node(name: &str) -> serde_json::Value {
        serde_json::json!({ "generic": name })
    }

    fn borrowed_generic(name: &str) -> serde_json::Value {
        serde_json::json!({ "borrowed_ref": { "lifetime": null, "mutable": false, "type_": { "generic": name } } })
    }

    fn tuple_of_generics(name: &str) -> serde_json::Value {
        serde_json::json!({ "tuple": [{ "generic": name }, { "generic": name }] })
    }

    /// Build a `fn_data` JSON for `resolve_generics` tests.  `inputs` is a list of
    /// type-JSON nodes (each becomes `["argN", <type>]`); `output` is the return.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn fn_data_with_generic_bounds(
        param_name: &str,
        bounds: Vec<serde_json::Value>,
        inputs: Vec<serde_json::Value>,
        output: serde_json::Value,
    ) -> serde_json::Value {
        let input_pairs: Vec<serde_json::Value> = inputs
            .into_iter()
            .enumerate()
            .map(|(i, t)| serde_json::json!([format!("arg{}", i), t]))
            .collect();
        serde_json::json!({
            "generics": {
                "params": [{
                    "name": param_name,
                    "kind": {
                        "type": {
                            "bounds": bounds,
                            "default": null,
                            "synthetic": false
                        }
                    }
                }],
                "where_predicates": []
            },
            "decl": {
                "inputs": input_pairs,
                "output": output
            }
        })
    }

    // ── C-G1: canonical path detection ───────────────────────────────────────

    #[test]
    fn serde_serialize_bound_detected() {
        let b = serde_bound("serde::Serialize");
        assert!(
            is_serde_trait_bound(&b),
            "serde::Serialize must be detected as a serde bound"
        );
    }

    #[test]
    fn serde_deserialize_owned_bound_detected() {
        let b = serde_bound("serde::de::DeserializeOwned");
        assert!(
            is_serde_trait_bound(&b),
            "serde::de::DeserializeOwned must be detected"
        );
    }

    #[test]
    fn own_serialize_look_alike_not_detected() {
        // A crate-local `trait Serialize` at crate_id=0 should NOT match.
        // In unit tests, the id 0 is NOT in EXTERNAL_TRAIT_PATH_BY_ID (nothing is
        // loaded), AND it IS confirmed local via LOCAL_TYPE_IDS being empty →
        // fallback fires on the raw path "Serialize" (no "::") → last segment
        // is "Serialize" but path is just "Serialize" which is NOT in
        // SERDE_TRAIT_PATHS (they all start with "serde::") → returns false.
        let b = serde_json::json!({
            "trait_bound": {
                "trait": {
                    "name": "Serialize",
                    "path": "Serialize",
                    "id": { "index": 1, "is_crate_root": false },
                    "args": null
                },
                "generic_params": [],
                "modifier": "none"
            }
        });
        assert!(
            !is_serde_trait_bound(&b),
            "crate-local Serialize must NOT be detected as serde"
        );
    }

