    // ── WALL 3a-&I (#65): admit a `&T` SERIALIZE (input) param ────────────────

    fn mut_borrowed_generic(name: &str) -> serde_json::Value {
        serde_json::json!({ "borrowed_ref": { "lifetime": null, "mutable": true, "type_": { "generic": name } } })
    }

    #[test]
    fn serialize_bound_is_serialize_only() {
        // Serialize ⇒ is_serialize_bound; Deserialize / DeserializeOwned ⇒ NOT.
        assert!(is_serialize_bound(&serde_bound("serde::Serialize")));
        assert!(is_serialize_bound(&serde_bound("serde::ser::Serialize")));
        assert!(!is_serialize_bound(&serde_bound(
            "serde::de::DeserializeOwned"
        )));
        assert!(!is_serialize_bound(&serde_bound("serde::de::Deserialize")));
        assert!(!is_serialize_bound(&marker_bound("Send")));
    }

    #[test]
    fn bounds_serialize_only_classification() {
        // Serialize (+ markers) ⇒ serialize-only. DeserializeOwned ⇒ NOT (output
        // shape). Serialize + DeserializeOwned ⇒ NOT (carries Deserialize). A
        // crate-local Serialize look-alike ⇒ NOT (not a real serde bound).
        assert!(bounds_are_serialize_only_or_marker(&[
            serde_bound("serde::Serialize"),
            marker_bound("Send"),
            marker_bound("Sync"),
        ]));
        assert!(!bounds_are_serialize_only_or_marker(&[serde_bound(
            "serde::de::DeserializeOwned"
        ),]));
        assert!(!bounds_are_serialize_only_or_marker(&[
            serde_bound("serde::Serialize"),
            serde_bound("serde::de::DeserializeOwned"),
        ]));
        assert!(
            !bounds_are_serialize_only_or_marker(&[]),
            "no serde bound → not serialize-only"
        );
    }

    #[test]
    fn serialize_input_ref_admissible_when_flag_set() {
        // `fn create_obj(&self, obj: &T)` with T serialize-only: a NON-MUT `&T`
        // in an INPUT position is ADMISSIBLE under the input-ref flag (the
        // codegen `&sv_j` ref-pass). The OWNED-only census (flag false) STILL
        // rejects it — proving the gate is exactly the new flag.
        let by_ref = borrowed_generic("T");
        assert!(
            serde_occurrence_admissible_in(&by_ref, "T", OccurrenceCtx::Admissible, true),
            "&T serialize INPUT must be admissible with the input-ref flag"
        );
        assert!(
            !serde_occurrence_admissible_in(&by_ref, "T", OccurrenceCtx::Admissible, false),
            "&T must stay inadmissible WITHOUT the flag (WALL-3a #59 baseline)"
        );
    }

    #[test]
    fn mut_serialize_input_ref_stays_inadmissible() {
        // `&mut T` is NEVER admitted, even with the input-ref flag — you cannot
        // hand a Ipe String as a mutable borrow of a to-be-serialised value.
        let by_mut = mut_borrowed_generic("T");
        assert!(
            !serde_occurrence_admissible_in(&by_mut, "T", OccurrenceCtx::Admissible, true),
            "&mut T must STAY inadmissible even with the input-ref flag"
        );
        assert!(!serde_occurrence_admissible_in(
            &by_mut,
            "T",
            OccurrenceCtx::Admissible,
            false
        ));
    }

    #[test]
    fn serialize_ref_inside_container_not_admitted() {
        // The flag admits ONLY a DIRECT top-level `&T`. A `&T` nested inside a
        // Vec (`Vec<&T>`) is NOT the sound `&owned` ref-pass shape → stays
        // inadmissible (the flag does not propagate into the container).
        let vec_of_ref = path_with_args("Vec", vec![borrowed_generic("T")]);
        assert!(
            !serde_occurrence_admissible_in(&vec_of_ref, "T", OccurrenceCtx::Admissible, true),
            "&T nested in Vec must NOT be admitted (only a direct top-level &T)"
        );
    }

    #[test]
    fn fn_ext_admits_serialize_input_ref_but_not_output_ref() {
        // INPUT `&T` admitted with the flag; an OUTPUT `&T` is NEVER admitted
        // (the output census always uses false). Build a fn whose output is `&T`.
        let in_ref = fn_data_with_generic_bounds(
            "T",
            vec![serde_bound("serde::Serialize")],
            vec![borrowed_generic("T")],
            serde_json::Value::Null,
        );
        assert!(
            fn_serde_param_all_admissible_ext(&in_ref, "T", true),
            "&T INPUT must pass the ext census with the flag"
        );
        assert!(
            !fn_serde_param_all_admissible(&in_ref, "T"),
            "&T INPUT must FAIL the owned-only census (baseline)"
        );

        // Output `&T` — the flag is dropped to false for the return census, so
        // it must FAIL even with allow_serialize_input_ref = true.
        let out_ref = fn_data_with_generic_bounds(
            "T",
            vec![serde_bound("serde::Serialize")],
            vec![],
            borrowed_generic("T"),
        );
        assert!(
            !fn_serde_param_all_admissible_ext(&out_ref, "T", true),
            "a borrowed `&T` RETURN must never be admitted (can't return a borrow \
             of a to-be-(de)serialised value)"
        );
    }

    #[test]
    fn fn_ext_mixed_owned_and_ref_input_admissible() {
        // `fn f(a: T, b: &T)` with T serialize-only: BOTH the owned `a: T` and
        // the by-ref `b: &T` are admissible under the input-ref flag — the
        // mixed case the firestore `create_obj` family hits when a method takes
        // both an owned and a borrowed serde value.
        let fd = fn_data_with_generic_bounds(
            "T",
            vec![serde_bound("serde::Serialize")],
            vec![generic_node("T"), borrowed_generic("T")],
            serde_json::Value::Null,
        );
        assert!(
            fn_serde_param_all_admissible_ext(&fd, "T", true),
            "owned + &T serialize inputs must both be admissible with the flag"
        );
        assert!(
            !fn_serde_param_all_admissible(&fd, "T"),
            "the same fn must DROP under the owned-only census (the &T vetoes)"
        );
    }

    #[test]
    fn serde_ref_borrowed_node_becomes_serde_value_ref() {
        // `type_to_typeref(&{__ipe_serde_value})` (non-mut) → SerdeValueRef.
        // `&mut {__ipe_serde_value}` → NotBindable (drops). This is the codegen
        // gate that pairs with the census admission.
        let pidx: HashMap<String, usize> = HashMap::new();
        let by_ref = serde_json::json!({
            "borrowed_ref": { "lifetime": null, "mutable": false,
                "type_": serde_json_value_node() } });
        assert_eq!(type_to_typeref(&by_ref, &pidx), Ok(TypeRef::SerdeValueRef));

        let by_mut = serde_json::json!({
            "borrowed_ref": { "lifetime": null, "mutable": true,
                "type_": serde_json_value_node() } });
        assert!(
            type_to_typeref(&by_mut, &pidx).is_err(),
            "&mut serde-Value must drop (no sound mutable-borrow ref-pass)"
        );
    }

    #[test]
    fn xc_send_output_resolves_via_proven_public_set() {
        // The `CustomerCreateCustomer.send` Output shape: a sibling manifest
        // crate's public type (`stripe_shared::Customer`) referenced from the
        // consuming crate, whose own paths cannot name it. `type_to_typeref` (the
        // send Output path) must resolve it via the manifest-run proven-public set
        // to the crate-qualified path — else the wrapper drops silently.
        REACHABLE_PATHS.with(|c| c.borrow_mut().clear());
        LOCAL_TYPE_IDS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_IDS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| c.borrow_mut().clear());
        EXTERNAL_DEFPATH_BY_ID.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATHS.with(|c| {
            c.borrow_mut().clear();
            c.borrow_mut().insert("stripe_shared::Customer".to_string());
        });
        // [W4] The identity-keyed map is the authority the two ambiguity sites now read:
        // one defining identity for `Customer`.
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            m.entry("stripe_shared::customer::Customer".to_string())
                .or_default()
                .insert("stripe_shared::Customer".to_string());
        });
        let pidx: HashMap<String, usize> = HashMap::new();
        let node = serde_json::json!({
            "resolved_path": { "name": "Customer", "path": "Customer", "id": 900, "args": null }
        });
        assert_eq!(
            type_to_typeref(&node, &pidx),
            Ok(TypeRef::Ctor(
                "::stripe_shared::Customer".to_string(),
                vec![]
            )),
            "the send Output must resolve to the proven-public sibling path"
        );
        // Without the proven-public entry it drops (fail-closed, pre-fix).
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| c.borrow_mut().clear());
        assert!(
            type_to_typeref(&node, &pidx).is_err(),
            "an unproven cross-crate type must still drop"
        );
    }

    #[test]
    fn xc_send_proven_admits_reexport_and_fails_closed_on_real_ambiguity() {
        // The `CreateCheckoutSession.send` Ok-Output `CheckoutSession` is owned by a
        // SIBLING manifest crate and rendered BARE in the consuming crate. The C1
        // async-Send gate proves it Send via the manifest-run cross-crate Send set.
        GLOBAL_XC_SEND_NAMES.with(|c| {
            let mut s = c.borrow_mut();
            s.clear();
            s.insert("stripe_shared::checkout_session::CheckoutSession".to_string());
            s.insert("stripe_shared::customer::Customer".to_string());
        });
        GLOBAL_XC_NONSEND_LASTSEGS.with(|c| c.borrow_mut().clear());
        // Bare last segment, matches a Send-proven entry, no same-named !Send type → Send.
        assert!(xc_send_proven("CheckoutSession"));
        assert!(xc_send_proven("Customer"));
        // The full path matches directly too.
        assert!(xc_send_proven(
            "stripe_shared::checkout_session::CheckoutSession"
        ));
        // An absent type never matches.
        assert!(!xc_send_proven("PaymentMethod"));
        // Compound / reference / generic shapes never match here.
        assert!(!xc_send_proven("List<CheckoutSession>"));
        assert!(!xc_send_proven("&CheckoutSession"));
        assert!(!xc_send_proven(""));

        // BENIGN RE-EXPORT: the SAME Send type re-exported from two member crates →
        // two Send-set entries share the last segment, and NO !Send type has that
        // segment → admit (a strict unique-match would have wrongly fail-closed here).
        GLOBAL_XC_SEND_NAMES.with(|c| {
            let mut s = c.borrow_mut();
            s.clear();
            s.insert("stripe_shared::checkout_session::CheckoutSession".to_string());
            s.insert("stripe_checkout::checkout_session::CheckoutSession".to_string());
        });
        GLOBAL_XC_NONSEND_LASTSEGS.with(|c| c.borrow_mut().clear());
        assert!(
            xc_send_proven("CheckoutSession"),
            "the same Send type re-exported by two member crates must still be admitted"
        );

        // REAL AMBIGUITY: a DIFFERENT, NON-Send type in some crate shares the last
        // segment → a bare reference could be either → FAIL CLOSED.
        GLOBAL_XC_NONSEND_LASTSEGS.with(|c| {
            c.borrow_mut().insert("CheckoutSession".to_string());
        });
        assert!(
            !xc_send_proven("CheckoutSession"),
            "a same-named non-Send type must make the bare reference fail closed"
        );
        // …but naming the FULL Send path is unambiguous and still admitted.
        assert!(xc_send_proven(
            "stripe_shared::checkout_session::CheckoutSession"
        ));

        GLOBAL_XC_SEND_NAMES.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_NONSEND_LASTSEGS.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn xc_public_path_admits_reexport_by_identity_and_fails_closed_on_collision() {
        // [W4] The return-nameability wall the create/checkout `send` hit. `CheckoutSession`
        // is DEFINED in `stripe_shared` and RE-EXPORTED by `stripe_checkout`, so the
        // manifest run has TWO valid public paths ending in `CheckoutSession`. The old
        // strict-unique last-segment match on the flat set fail-closed here (two hits) and
        // the Output could not be named. Identity keying collapses both under the SAME
        // defining path → admit one deterministic public path.
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            // One defining identity, two public paths (a genuine re-export).
            let e = m
                .entry("stripe_shared::checkout_session::CheckoutSession".to_string())
                .or_default();
            e.insert("stripe_shared::CheckoutSession".to_string());
            e.insert("stripe_checkout::CheckoutSession".to_string());
        });
        assert_eq!(
            xc_public_path_for_last_segment("CheckoutSession"),
            Some("stripe_checkout::CheckoutSession".to_string()),
            "a genuine re-export (one defining identity, N public paths) must admit a \
             deterministic path — the lexicographically smallest"
        );
        // An absent last segment never resolves.
        assert_eq!(xc_public_path_for_last_segment("PaymentMethod"), None);
        assert_eq!(xc_public_path_for_last_segment(""), None);

        // REAL COLLISION: two DISTINCT defining types share the last segment `Config`
        // (e.g. `crate_a::Config` and `crate_b::Config` are different types) → naming
        // either could be the WRONG type → FAIL CLOSED.
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            m.entry("crate_a::settings::Config".to_string())
                .or_default()
                .insert("crate_a::Config".to_string());
            m.entry("crate_b::opts::Config".to_string())
                .or_default()
                .insert("crate_b::Config".to_string());
        });
        assert_eq!(
            xc_public_path_for_last_segment("Config"),
            None,
            "two distinct same-named defining types must fail closed (no wrong-type pick)"
        );
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn type_to_typeref_names_reexported_send_output_via_identity() {
        // [W4] End-to-end at the `type_to_typeref` return-nameability site: the
        // `CreateCheckoutSession.send` Output `CheckoutSession`, reachable from two member
        // crates as a genuine re-export, must NAME (via the identity map) — the whole
        // point of W4 (pre-fix it dropped on the two-hit ambiguity).
        REACHABLE_PATHS.with(|c| c.borrow_mut().clear());
        LOCAL_TYPE_IDS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_IDS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| c.borrow_mut().clear());
        EXTERNAL_DEFPATH_BY_ID.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            let e = m
                .entry("stripe_shared::checkout_session::CheckoutSession".to_string())
                .or_default();
            e.insert("stripe_shared::CheckoutSession".to_string());
            e.insert("stripe_checkout::CheckoutSession".to_string());
        });
        let pidx: HashMap<String, usize> = HashMap::new();
        let node = serde_json::json!({
            "resolved_path": { "name": "CheckoutSession", "path": "CheckoutSession", "id": 901, "args": null }
        });
        assert_eq!(
            type_to_typeref(&node, &pidx),
            Ok(TypeRef::Ctor(
                "::stripe_checkout::CheckoutSession".to_string(),
                vec![]
            )),
            "the re-exported send Output must resolve to a proven-public path (W4)"
        );
        // A genuinely colliding pair of distinct types keeps the Output unnameable.
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            m.entry("a::x::CheckoutSession".to_string())
                .or_default()
                .insert("a::CheckoutSession".to_string());
            m.entry("b::y::CheckoutSession".to_string())
                .or_default()
                .insert("b::CheckoutSession".to_string());
        });
        assert!(
            type_to_typeref(&node, &pidx).is_err(),
            "two distinct same-named types must still drop (fail-closed)"
        );
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn is_provably_send_opaque_return_consults_xc_send_set() {
        // End-to-end at the C1 output gate: a bare cross-crate Send payload passes
        // `is_provably_send_opaque_return` ONLY when the cross-crate Send set proves it.
        PROVABLY_SEND_RECV_NAMES.with(|c| c.borrow_mut().clear());
        PROVABLY_SEND_OPAQUE_NAMES.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_SEND_NAMES.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_NONSEND_LASTSEGS.with(|c| c.borrow_mut().clear());
        assert!(
            !is_provably_send_opaque_return("CheckoutSession"),
            "unproven bare cross-crate type must not be Send-admitted"
        );
        GLOBAL_XC_SEND_NAMES.with(|c| {
            c.borrow_mut()
                .insert("stripe_shared::checkout_session::CheckoutSession".to_string());
        });
        assert!(
            is_provably_send_opaque_return("CheckoutSession"),
            "a sibling-proven Send payload must now pass the C1 output gate"
        );
        GLOBAL_XC_SEND_NAMES.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn non_serde_bound_not_reduced() {
        // `fn f<T: Display>(x: T)` → NOT reduced (Display is not serde).
        let display_bound = serde_json::json!({
            "trait_bound": {
                "trait": { "name": "Display", "path": "core::fmt::Display", "id": { "index": 0, "is_crate_root": false }, "args": null },
                "generic_params": [], "modifier": "none"
            }
        });
        let fd = fn_data_with_generic_bounds(
            "T",
            vec![display_bound.clone()],
            vec![generic_node("T")],
            serde_json::Value::Null,
        );
        // Display IS handled by bound_to_concrete → resolves to String, not dropped.
        // The point is it does NOT yield a serde_json_value_node.
        let map = resolve_generics(&fd);
        if let Some(ref m) = map {
            assert_ne!(
                m.get("T"),
                Some(&serde_json_value_node()),
                "Display bound must NOT produce serde_json_value sentinel"
            );
        }
        // (resolve_generics may return Some(string_node()) or None for Display — both ok)
    }

