    // ── R1/R2/R3 regression tests (#48) ──────────────────────────────────────

    /// R1 [#48]: A single-segment type name at the very start of a type string
    /// preceded only by `::` (i.e. `::TypeId`) has `start == 2` and MUST be
    /// unnameable.  The pre-fix bug treated it as "qualified" (start >= 2 caught
    /// this case and wrongly allowed it through).
    #[test]
    fn test_r1_leading_colons_single_segment_unnameable() {
        // `::TypeId` — the identifier starts at index 2, preceded only by "::".
        // No module before the leading colons → unnameable (can't import).
        assert!(
            !type_is_nameable("::TypeId"),
            "::TypeId (no module before leading ::) must be unnameable"
        );
        // Contrast: a genuinely module-qualified name (module before the segment)
        // IS nameable.
        assert!(
            type_is_nameable("std::any::TypeId"),
            "std::any::TypeId is module-qualified and must be nameable"
        );
        // Sanity: a plain bare uppercase that is not in ALWAYS_NAMEABLE is unnameable.
        assert!(
            !type_is_nameable("TypeId"),
            "bare TypeId (not in ALWAYS_NAMEABLE) must be unnameable"
        );
        // A return like `-> ::SomePrivate` at start-of-string is the real cargo-fail
        // class this fixes (Any::type_id → TypeId, ToOwned → Owned).
        assert!(
            !type_is_nameable("::Owned"),
            "::Owned (no module prefix) must be unnameable"
        );
    }

    /// R2 [#48]: `alloc::borrow::ToOwned` recorded by `collect_external_trait_paths`
    /// must be remapped to `std::borrow::ToOwned` so the emitted UFCS qualifier
    /// `::std::borrow::ToOwned` compiles under the normal std-linked target.
    /// `::alloc::borrow::ToOwned` would fail (E0433: `alloc` not in scope).
    #[test]
    fn test_r2_alloc_trait_path_remapped_to_std() {
        let doc = serde_json::json!({
            "index": {
                "1": { "name": "mycrate", "crate_id": 0, "visibility": "public",
                       "inner": { "module": { "items": [] } } }
            },
            "paths": {
                // `alloc::borrow::ToOwned` as rustdoc would record it
                "300": { "crate_id": 1, "kind": "trait",
                         "path": ["alloc", "borrow", "ToOwned"] }
            },
        });
        let paths = collect_external_trait_paths(&doc);
        let stored = paths.get("300").expect("trait 300 must be recorded");
        assert_eq!(
            stored, "std::borrow::ToOwned",
            "alloc::borrow::ToOwned must be remapped to std::borrow::ToOwned"
        );
        assert!(
            !stored.starts_with("alloc::"),
            "stored path must NOT start with alloc:: (not importable)"
        );
    }

    /// WALL-B [#75]: the SECOND `external_trait_path` resolution path — recovery
    /// via `STD_TRAIT_BY_ID` tag → `STD_TRAIT_CANONICAL` lookup — must ALSO remap
    /// `alloc::` to `std::`. `STD_TRAIT_CANONICAL` lists the `alloc::` form FIRST
    /// for the heap traits (`alloc::string::ToString`, `alloc::borrow::ToOwned`),
    /// so the `.find(|(_, t)| *t == tag)` returns it. Pre-fix the firebase
    /// `ApiClientError: ToString` wrapper emitted
    /// `<… as ::alloc::string::ToString>::to_string` → E0433 `could not find
    /// alloc`. `remap_alloc_to_std` closes it.
    #[test]
    fn test_wall_b_remap_alloc_to_std() {
        assert_eq!(
            remap_alloc_to_std("alloc::string::ToString"),
            "std::string::ToString"
        );
        assert_eq!(
            remap_alloc_to_std("alloc::borrow::ToOwned"),
            "std::borrow::ToOwned"
        );
        // Non-alloc paths are untouched.
        assert_eq!(
            remap_alloc_to_std("core::fmt::Display"),
            "core::fmt::Display"
        );
        assert_eq!(
            remap_alloc_to_std("std::string::ToString"),
            "std::string::ToString"
        );
        assert_eq!(remap_alloc_to_std("http::HeaderMap"), "http::HeaderMap");
        // The canonical-table entry for the ToString tag is the `alloc::` form;
        // confirm the remap turns it into the importable `std::` re-export.
        let canonical = STD_TRAIT_CANONICAL
            .iter()
            .find(|(_, t)| *t == "ToString")
            .map(|(p, _)| *p)
            .expect("ToString must be in STD_TRAIT_CANONICAL");
        assert_eq!(
            canonical, "alloc::string::ToString",
            "table still lists the alloc:: form first (the bug's source)"
        );
        assert_eq!(
            remap_alloc_to_std(canonical),
            "std::string::ToString",
            "external_trait_path must emit the std:: re-export, not ::alloc::"
        );
    }

    /// R3 [#48]: A type produced only inside `Result<T, E>` (e.g. `url::Url`
    /// from `Url::parse`) must be admitted to `owned_producible` so its instance
    /// methods survive the Sized gate (P4).  The fix unwraps one layer of
    /// Result/Option when building the set.
    #[test]
    fn test_r3_owned_producible_unwraps_result_inner() {
        // Simulate the owned_producible logic directly.
        // A function returning `Result<url::Url, url::ParseError>` — the inner
        // `url::Url` must land in owned_producible even though the outer type is
        // the container.
        let inner_owned = |rt: &str| -> Option<String> {
            let t = rt.trim();
            if let Some(rest) = t.strip_prefix("Result<") {
                let rest = rest.strip_suffix('>')?;
                let mut depth: usize = 0;
                for (i, c) in rest.char_indices() {
                    match c {
                        '<' => depth += 1,
                        '>' => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        ',' if depth == 0 => {
                            let inner = rest[..i].trim().to_string();
                            let owned =
                                !inner.is_empty() && !inner.contains('&') && !inner.contains('[');
                            if owned {
                                return Some(inner);
                            }
                            return None;
                        }
                        _ => {}
                    }
                }
                return None;
            }
            if let Some(inner) = t.strip_prefix("Option<").and_then(|r| r.strip_suffix('>')) {
                let inner = inner.trim().to_string();
                let owned = !inner.is_empty() && !inner.contains('&') && !inner.contains('[');
                if owned {
                    return Some(inner);
                }
            }
            None
        };

        // Result<url::Url, url::ParseError> → inner = "url::Url"
        assert_eq!(
            inner_owned("Result<url::Url, url::ParseError>"),
            Some("url::Url".to_string()),
            "Result<url::Url, url::ParseError> must yield inner url::Url"
        );
        // Option<url::Url> → inner = "url::Url"
        assert_eq!(
            inner_owned("Option<url::Url>"),
            Some("url::Url".to_string()),
            "Option<url::Url> must yield inner url::Url"
        );
        // Borrowed inner is NOT owned → None
        assert_eq!(
            inner_owned("Result<&str, String>"),
            None,
            "Result<&str, _> inner is borrowed — must NOT be admitted"
        );
        // Plain type (no wrapper) → None (not the job of inner_owned)
        assert_eq!(
            inner_owned("url::Url"),
            None,
            "bare url::Url is not a Result/Option — inner_owned returns None"
        );
    }

    // ── #49: facade re-export guidance ───────────────────────────────────────

    /// Facade crate (0 fns) with a public glob `pub use ext_crate::*` →
    /// guidance names the external crate.
    #[test]
    fn test_facade_guidance_names_subcrate() {
        // Minimal rustdoc JSON:
        // - item "1" = the crate root module (crate_id=0)
        // - item "2" = a `use` item (crate_id=0, is_glob=true) whose target id=3
        // - item "3" = an item from external crate (crate_id=7)
        // external_crates[7] = { name: "other_crate" }
        let doc = serde_json::json!({
            "index": {
                "1": {
                    "name": "facade_crate",
                    "crate_id": 0,
                    "visibility": "public",
                    "inner": { "module": { "items": ["2"] } }
                },
                "2": {
                    "name": "",
                    "crate_id": 0,
                    "visibility": "public",
                    "inner": {
                        "use": {
                            "source": "other_crate",
                            "name": "*",
                            "id": 3,
                            "is_glob": true
                        }
                    }
                },
                "3": {
                    "name": "some_fn",
                    "crate_id": 7,
                    "visibility": "public",
                    "inner": { "function": {} }
                }
            },
            "external_crates": {
                "7": { "name": "other_crate", "html_root_url": null }
            },
            "paths": {},
            "format_version": 38
        });

        let notes = facade_guidance("facade_crate", 0, &doc);
        assert_eq!(
            notes.len(),
            1,
            "facade with 0 fns must produce exactly one note"
        );
        let note = &notes[0];
        assert!(
            note.contains("other_crate"),
            "note must name the sub-crate: {note}"
        );
        assert!(
            note.starts_with("note: 'facade_crate' re-exports its API from:"),
            "note must use the expected prefix format: {note}"
        );
        assert!(
            note.contains("ipe add other_crate"),
            "note must suggest the ipe add command: {note}"
        );
    }

    /// #53: a crate with a real own API (≥3 fns) AND an external glob re-export
    /// gets the SUPPLEMENTARY ("also re-exports") note — naming the sub-crate is
    /// helpful even when some own API bound. (Pre-#53 this suppressed on
    /// `fn_count`, hiding the hint for glue-heavy facades like async-stripe.)
    #[test]
    fn test_facade_guidance_supplementary_for_reexporting_crate() {
        // Same doc structure but fn_count = 5 → supplementary wording.
        let doc = serde_json::json!({
            "index": {
                "1": {
                    "name": "normal_crate",
                    "crate_id": 0,
                    "visibility": "public",
                    "inner": { "module": { "items": ["2"] } }
                },
                "2": {
                    "name": "",
                    "crate_id": 0,
                    "visibility": "public",
                    "inner": {
                        "use": {
                            "source": "other_crate",
                            "name": "*",
                            "id": 3,
                            "is_glob": true
                        }
                    }
                },
                "3": {
                    "name": "some_fn",
                    "crate_id": 7,
                    "visibility": "public",
                    "inner": { "function": {} }
                }
            },
            "external_crates": {
                "7": { "name": "other_crate", "html_root_url": null }
            },
            "paths": {},
            "format_version": 38
        });

        let notes = facade_guidance("normal_crate", 5, &doc);
        assert_eq!(
            notes.len(),
            1,
            "a crate with an external glob re-export must produce a note even at 5 fns: {notes:?}"
        );
        let note = &notes[0];
        assert!(
            note.contains("also re-exports items from:"),
            "≥-threshold fn_count must use the supplementary wording: {note}"
        );
        assert!(
            note.contains("other_crate") && note.contains("ipe add other_crate"),
            "supplementary note must still name the sub-crate + add command: {note}"
        );
    }

