    /// Facade naming TWO distinct sub-crates (multiple glob re-exports).
    #[test]
    fn test_facade_guidance_multiple_subcrates() {
        let doc = serde_json::json!({
            "index": {
                "1": { "name": "meta", "crate_id": 0, "visibility": "public",
                       "inner": { "module": { "items": ["2", "4"] } } },
                "2": { "name": "", "crate_id": 0, "visibility": "public",
                       "inner": { "use": { "source": "alpha", "name": "*",
                                           "id": 3, "is_glob": true } } },
                "3": { "name": "alpha_fn", "crate_id": 10, "visibility": "public",
                       "inner": { "function": {} } },
                "4": { "name": "", "crate_id": 0, "visibility": "public",
                       "inner": { "use": { "source": "beta", "name": "*",
                                           "id": 5, "is_glob": true } } },
                "5": { "name": "beta_fn", "crate_id": 11, "visibility": "public",
                       "inner": { "function": {} } }
            },
            "external_crates": {
                "10": { "name": "alpha", "html_root_url": null },
                "11": { "name": "beta",  "html_root_url": null }
            },
            "paths": {},
            "format_version": 38
        });

        let notes = facade_guidance("meta", 0, &doc);
        assert_eq!(notes.len(), 1);
        let note = &notes[0];
        assert!(note.contains("alpha"), "note must contain 'alpha': {note}");
        assert!(note.contains("beta"), "note must contain 'beta': {note}");
    }

    // ── [WALL 5 / #63] generic Result-alias see-through ──────────────────
    //
    // The firestore-gating shape: a crate-local GENERIC alias
    // `type DbResult<T> = Result<T, DbError>` must be expanded at the use site
    // so the async-Send output gate's `Result<…>`-unwrap can reach the inner
    // type.  These tests pin: (a) the canonical Result/Option alias expands,
    // (b) the inner type survives expansion (incl. a `Box<dyn>` inner that the
    // DOWNSTREAM gate still drops), (c) a non-Result generic alias is NOT
    // expanded, (d) arity mismatch fails closed.

    /// A rustdoc generic type-alias INDEX item: `type Name<params…> = body`.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn generic_alias_item(
        name: &str,
        params: &[&str],
        body: serde_json::Value,
    ) -> serde_json::Value {
        let params_json: Vec<serde_json::Value> = params
            .iter()
            .map(|p| {
                serde_json::json!({
                    "name": p,
                    "kind": { "type": { "bounds": [], "default": null, "is_synthetic": false } }
                })
            })
            .collect();
        serde_json::json!({
            "name": name,
            "crate_id": 0,
            "inner": {
                "type_alias": {
                    "type": body,
                    "generics": { "params": params_json, "where_predicates": [] }
                }
            }
        })
    }

    /// `resolved_path` to a body constructor with the given rustdoc id + args.
    fn rp_with_id(name: &str, id: u64, args: Vec<serde_json::Value>) -> serde_json::Value {
        let type_args: Vec<serde_json::Value> = args
            .into_iter()
            .map(|t| serde_json::json!({ "type": t }))
            .collect();
        serde_json::json!({
            "resolved_path": {
                "name": name, "path": name, "id": id,
                "args": { "angle_bracketed": { "args": type_args, "constraints": [] } }
            }
        })
    }

    /// A `paths` map proving id 100 is the canonical external `core::result::Result`
    /// and id 101 is `core::option::Option`.
    fn std_result_option_paths() -> serde_json::Value {
        serde_json::json!({
            "100": { "crate_id": 2, "kind": "enum", "path": ["core", "result", "Result"] },
            "101": { "crate_id": 2, "kind": "enum", "path": ["core", "option", "Option"] }
        })
    }

    /// Build a doc whose index holds a single generic alias item at id 48, with
    /// std-provenance paths, run `collect_generic_result_aliases`, and install the
    /// result into `GENERIC_ALIAS_MAP` for the converters to consult.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn install_generic_alias(item: serde_json::Value) {
        let doc = serde_json::json!({
            "index": { "48": item },
            "paths": std_result_option_paths()
        });
        let map = collect_generic_result_aliases(&doc);
        GENERIC_ALIAS_MAP.with(|c| *c.borrow_mut() = map);
    }

    /// A use-site `resolved_path` referencing the installed alias (id 48) with the
    /// given use-site type args.
    fn alias_use(args: Vec<serde_json::Value>) -> serde_json::Value {
        let type_args: Vec<serde_json::Value> = args
            .into_iter()
            .map(|t| serde_json::json!({ "type": t }))
            .collect();
        serde_json::json!({
            "resolved_path": {
                "name": "DbResult", "path": "DbResult", "id": 48,
                "args": { "angle_bracketed": { "args": type_args, "constraints": [] } }
            }
        })
    }

    #[test]
    fn wall5_result_alias_expands_rust_and_ipe() {
        // type DbResult<T> = Result<T, DbError>   (DbError is crate-local id 7)
        let body = rp_with_id("Result", 100, vec![generic_node("T"), path("DbError")]);
        install_generic_alias(generic_alias_item("DbResult", &["T"], body));

        // DbResult<Db>  →  Result<Db, DbError> (rust)  /  Result DbError Db (ipe)
        let use_site = alias_use(vec![path("Db")]);
        assert_eq!(rustdoc_type_to_rust_str(&use_site), "Result<Db, DbError>");
        assert_eq!(ipe(&use_site), "Result DbError Db");
    }

    #[test]
    fn wall5_result_alias_inner_box_dyn_survives_for_downstream_drop() {
        // The see-through expands the OUTER Result; the inner Box<dyn …> must be
        // rendered intact so the (separate) async-Send / nameability gate drops it.
        // We assert the rendered rust string carries the Box<dyn …> verbatim.
        let body = rp_with_id("Result", 100, vec![generic_node("T"), path("DbError")]);
        install_generic_alias(generic_alias_item("DbResult", &["T"], body));

        let boxed_dyn = serde_json::json!({
            "resolved_path": {
                "name": "Box", "path": "Box", "id": 0,
                "args": { "angle_bracketed": { "args": [
                    { "type": { "dyn_trait": { "traits": [], "lifetime": null } } }
                ], "constraints": [] } }
            }
        });
        let use_site = alias_use(vec![boxed_dyn]);
        let rust = rustdoc_type_to_rust_str(&use_site);
        assert!(
            rust.starts_with("Result<"),
            "outer Result must expand: {rust}"
        );
        // The inner stays a Box (the downstream gate, not the see-through, drops it).
        assert!(
            rust.contains("Box"),
            "inner Box must survive expansion: {rust}"
        );
    }

    /// [#66] A CYCLIC crate-local alias (`type DbResult<T> = Result<DbResult<T>, E>`)
    /// — which rustc rejects as E0275 and therefore never emits, but a hand-crafted
    /// JSON could carry — must TERMINATE via the `AliasDepthGuard` bound rather than
    /// stack-overflow this build-time tool. The renderer fails closed: it expands
    /// up to the bound then renders the inner alias OPAQUE. The test PASSING (not
    /// hanging/aborting) is itself the termination proof; we also assert the output
    /// is bounded + contains the opaque inner name at the truncation point.
    // ── stripe-send F2 — a cross-crate Output type nameable only via a sibling
    //    manifest crate's proven-public path (the `stripe_shared::Customer` shape).
    #[test]
    fn xc_public_path_renders_when_a_sibling_crate_proved_it_public() {
        // The consuming crate's own `doc["paths"]` records the referenced external
        // item's canonical path, but `reachable_local_path` misses (not
        // crate-local). Without the proven-public set the renderer falls to the
        // bare last segment (`Customer`), which the nameability filter drops — the
        // exact `CustomerCreateCustomer.send` Output drop.
        REACHABLE_PATHS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| {
            c.borrow_mut().clear();
            c.borrow_mut()
                .insert("777".to_string(), "stripe_shared::Customer".to_string());
        });
        let node = serde_json::json!({
            "resolved_path": { "name": "Customer", "path": "Customer", "id": 777, "args": null }
        });
        // Not yet in the proven-public set → falls to the bare segment (dropped
        // downstream, the pre-fix behaviour).
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        assert_eq!(rustdoc_type_to_rust_str(&node), "Customer");
        // A SIBLING member crate's reachable walk proved it public → the renderer
        // keeps the crate-qualified path, so the Output is nameable and `send`
        // binds.
        GLOBAL_XC_PUBLIC_PATHS.with(|c| {
            c.borrow_mut().insert("stripe_shared::Customer".to_string());
        });
        assert_eq!(rustdoc_type_to_rust_str(&node), "stripe_shared::Customer");
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| c.borrow_mut().clear());
        EXTERNAL_DEFPATH_BY_ID.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn xc_public_path_never_admits_an_unproven_external_path() {
        // A def-path threading a private module of a non-member crate was never
        // recorded into the proven-public set (`external_type_public_path` fail-
        // closes it), so even present in EXTERNAL_TYPE_PATH_BY_ID it stays dropped
        // — the private-module trap stays closed.
        REACHABLE_PATHS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| {
            c.borrow_mut().clear();
            c.borrow_mut()
                .insert("778".to_string(), "krate::private_mod::Secret".to_string());
        });
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| c.borrow_mut().clear());
        let node = serde_json::json!({
            "resolved_path": { "name": "Secret", "path": "Secret", "id": 778, "args": null }
        });
        assert_eq!(rustdoc_type_to_rust_str(&node), "Secret");
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| c.borrow_mut().clear());
        EXTERNAL_DEFPATH_BY_ID.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn rust_str_renders_reexported_output_via_identity_when_defpath_fails_closed() {
        // [W4] The `rust_type` render path (`rustdoc_type_to_rust_str`) — the source the
        // C1 async-Send gate and the emitter read. The create/checkout `send` Output
        // `Customer`/`CheckoutSession` is DEFINED in a sibling submodule
        // (`stripe_shared::customer::Customer`), so `external_type_public_path` fail-closes
        // it out of EXTERNAL_TYPE_PATH_BY_ID (rule 5: non-std intermediate module). Without
        // the identity fall-through the render is BARE `Customer` → the emitter absolutizes
        // it to `::Customer` → E0433 / silent drop, even though `type_to_typeref` already
        // names it. The identity map (populated from the DEFINING crate's own reachable
        // walk) supplies the proven-public path so both render paths agree.
        REACHABLE_PATHS.with(|c| c.borrow_mut().clear());
        EXTERNAL_TYPE_PATH_BY_ID.with(|c| c.borrow_mut().clear());
        EXTERNAL_DEFPATH_BY_ID.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATHS.with(|c| c.borrow_mut().clear());
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            let e = m
                .entry("stripe_shared::customer::Customer".to_string())
                .or_default();
            e.insert("stripe_shared::Customer".to_string());
        });
        let node = serde_json::json!({
            "resolved_path": { "name": "Customer", "path": "Customer", "id": 555, "args": null }
        });
        assert_eq!(
            rustdoc_type_to_rust_str(&node),
            "stripe_shared::Customer",
            "the render path must qualify a sibling-defined re-exported Output via identity"
        );
        // Fail-closed on a genuine collision — two distinct same-named defining types.
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| {
            let mut m = c.borrow_mut();
            m.clear();
            m.entry("a::x::Customer".to_string())
                .or_default()
                .insert("a::Customer".to_string());
            m.entry("b::y::Customer".to_string())
                .or_default()
                .insert("b::Customer".to_string());
        });
        assert_eq!(
            rustdoc_type_to_rust_str(&node),
            "Customer",
            "a real collision stays bare (fail-closed), never a wrong-type pick"
        );
        GLOBAL_XC_PUBLIC_PATH_BY_DEFID.with(|c| c.borrow_mut().clear());
    }

    #[test]
    fn wall5_cyclic_alias_terminates_fail_closed() {
        // body = Result<DbResult<T>, DbError>  (the first arg is the alias itself)
        let cyclic_self = rp_with_id("DbResult", 48, vec![generic_node("T")]);
        let body = rp_with_id("Result", 100, vec![cyclic_self, path("DbError")]);
        install_generic_alias(generic_alias_item("DbResult", &["T"], body));

        let use_site = alias_use(vec![path("Db")]);
        // Both renderers must return (no infinite recursion) and stay bounded.
        let rust = rustdoc_type_to_rust_str(&use_site);
        let s = ipe(&use_site);
        assert!(
            rust.starts_with("Result<"),
            "outer Result must expand once: {rust}"
        );
        assert!(
            rust.contains("DbResult"),
            "inner cyclic alias must render OPAQUE at the depth bound: {rust}"
        );
        // Bounded: ~one `Result<…>` wrap per level up to the cap, never unbounded.
        assert!(
            rust.len() < 4096,
            "rendered string must be bounded: len={}",
            rust.len()
        );
        assert!(
            !s.is_empty(),
            "ipe rendering must also terminate non-empty: {s}"
        );
        // Depth counter must have unwound back to 0 (RAII balance).
        ALIAS_SEE_THROUGH_DEPTH.with(|d| assert_eq!(d.get(), 0, "depth must unwind to 0"));
    }

    #[test]
    fn wall5_option_alias_expands() {
        // type Opt<T> = Option<T>  →  Maybe T
        let body = rp_with_id("Option", 101, vec![generic_node("T")]);
        install_generic_alias(generic_alias_item("Opt", &["T"], body));
        let use_site = alias_use(vec![path("Db")]);
        assert_eq!(ipe(&use_site), "Maybe Db");
        assert_eq!(rustdoc_type_to_rust_str(&use_site), "Option<Db>");
    }

    #[test]
    fn wall5_non_result_generic_alias_not_expanded() {
        // type Wrap<T> = Vec<T>  — body outer ctor is Vec, NOT Result/Option.
        // collect_generic_result_aliases must NOT record it; GENERIC_ALIAS_MAP
        // empty -> use site renders opaquely (the pre-fix behaviour).
        let body = rp_with_id("Vec", 200, vec![generic_node("T")]);
        let doc = serde_json::json!({
            "index": { "48": generic_alias_item("Wrap", &["T"], body) },
            "paths": std_result_option_paths()
        });
        let map = collect_generic_result_aliases(&doc);
        assert!(
            map.is_empty(),
            "non-Result generic alias must NOT be recorded"
        );
        GENERIC_ALIAS_MAP.with(|c| *c.borrow_mut() = map);
        // The use site falls through to opaque rendering: the bare alias name.
        let use_site = alias_use(vec![path("Db")]);
        assert_eq!(rustdoc_type_to_rust_str(&use_site), "DbResult<Db>");
    }

    #[test]
    fn wall5_crate_local_result_homonym_not_expanded() {
        // A crate-local type NAMED `Result` (crate_id 0 in paths) must NOT be
        // treated as the std Result — provenance gate rejects it.
        let body = rp_with_id("Result", 300, vec![generic_node("T"), path("DbError")]);
        let doc = serde_json::json!({
            "index": { "48": generic_alias_item("DbResult", &["T"], body) },
            // id 300 is a CRATE-LOCAL "Result" homonym (crate_id 0).
            "paths": { "300": { "crate_id": 0, "kind": "enum", "path": ["mycrate", "Result"] } }
        });
        let map = collect_generic_result_aliases(&doc);
        assert!(
            map.is_empty(),
            "crate-local Result homonym must NOT be recorded"
        );
    }

    #[test]
    fn wall5_arity_mismatch_fails_closed() {
        // type Pair<A, B> = Result<A, B>  (2 params) used with ONE arg -> no expand.
        let body = rp_with_id("Result", 100, vec![generic_node("A"), generic_node("B")]);
        install_generic_alias(generic_alias_item("Pair", &["A", "B"], body));
        // Use site supplies only one type arg -> arity mismatch -> fail closed.
        let use_site = alias_use(vec![path("Db")]);
        assert!(
            expand_generic_alias(use_site.get("resolved_path").unwrap()).is_none(),
            "arity mismatch must yield None (fail closed)"
        );
        // And the rendered string stays the opaque alias (no half-substitution).
        assert_eq!(rustdoc_type_to_rust_str(&use_site), "DbResult<Db>");
    }

    #[test]
    fn wall5_nested_generic_substitutes_totally() {
        // type DbResult<T> = Result<Vec<T>, DbError>  — nested generic.
        // Use site DbResult<Db> must substitute T inside the nested Vec, leaving
        // NO residual {generic:"T"} (which would render an undeclared type-var).
        let vec_t = rp_with_id("Vec", 201, vec![generic_node("T")]);
        let body = rp_with_id("Result", 100, vec![vec_t, path("DbError")]);
        install_generic_alias(generic_alias_item("DbResult", &["T"], body));
        let use_site = alias_use(vec![path("Db")]);
        let rust = rustdoc_type_to_rust_str(&use_site);
        assert_eq!(rust, "Result<Vec<Db>, DbError>");
        assert!(
            !rust.contains('T') || rust.contains("DbError"),
            "no residual bare type-var T: {rust}"
        );
    }

    #[test]
    fn wall5_self_inner_preserved_for_subst_self() {
        // The firestore real shape uses `DbResult<Self>` at the use site; the
        // see-through substitutes T <- {generic:"Self"}, keeping `Self` for the
        // later string-level subst_self(recv) pass.
        let body = rp_with_id("Result", 100, vec![generic_node("T"), path("DbError")]);
        install_generic_alias(generic_alias_item("DbResult", &["T"], body));
        let use_site = alias_use(vec![generic_node("Self")]);
        // Rendered with Self intact (subst_self maps it to the receiver downstream).
        assert_eq!(rustdoc_type_to_rust_str(&use_site), "Result<Self, DbError>");
        assert_eq!(
            subst_self(&rustdoc_type_to_rust_str(&use_site), "Db"),
            "Result<Db, DbError>"
        );
    }

    // ── WALL 4 / #64 — `#[async_trait]` desugar recognition ──────────────────
    //
    // The proc-macro rewrites `async fn m(..) -> T` into a PLAIN (non-async)
    // `fn m(..) -> Pin<Box<dyn Future<Output=T> + Send + 'async_trait>>`. The
    // tests encode the empirically-confirmed §1 rustdoc node verbatim and prove:
    // recognition, Output extraction via `constraints[]` (the make-or-break),
    // Send requirement, canonical-Future gate (#25 class), is_async-on-CLONE.

    /// A `resolved_path` node with a single angle-bracketed TYPE arg.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn rp1(path_name: &str, id: u64, inner: serde_json::Value) -> serde_json::Value {
        serde_json::json!({ "resolved_path": {
            "path": path_name, "name": path_name, "id": id,
            "args": { "angle_bracketed": { "args": [ { "type": inner } ], "constraints": [] } }
        } })
    }

    /// A `dyn Trait` node: principal `trait_principal`, optional auto-trait bounds
    /// (each `(path, id)`), and an `Output = out` constraint on the principal.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn dyn_future_node(
        principal_path: &str,
        principal_id: u64,
        out: serde_json::Value,
        autos: &[(&str, u64)],
    ) -> serde_json::Value {
        let mut traits = vec![serde_json::json!({
            "trait": {
                "path": principal_path, "name": principal_path, "id": principal_id,
                "args": { "angle_bracketed": {
                    "args": [],
                    "constraints": [ {
                        "name": "Output", "args": null,
                        "binding": { "equality": { "type": out } }
                    } ]
                } }
            },
            "generic_params": []
        })];
        for (p, id) in autos {
            traits.push(serde_json::json!({
                "trait": { "path": p, "name": p, "id": id, "args": null },
                "generic_params": []
            }));
        }
        serde_json::json!({ "dyn_trait": { "traits": traits, "lifetime": "'async_trait" } })
    }

    /// `Pin<Box<dyn Future<Output=out> + <autos>>>` — the `async_trait` return box.
    fn async_trait_box(
        out: serde_json::Value,
        principal_path: &str,
        principal_id: u64,
        autos: &[(&str, u64)],
    ) -> serde_json::Value {
        let dt = dyn_future_node(principal_path, principal_id, out, autos);
        rp1("::core::pin::Pin", 2, rp1("Box", 3, dt))
    }

    /// `Result<i64, String>` — the canonical `async_trait` Output of the §1 probe.
    fn result_i64_string() -> serde_json::Value {
        serde_json::json!({ "resolved_path": {
            "path": "Result", "name": "Result", "id": 5,
            "args": { "angle_bracketed": { "args": [
                { "type": { "primitive": "i64" } },
                { "type": { "resolved_path": { "path": "String", "name": "String", "id": 1, "args": null } } }
            ], "constraints": [] } }
        } })
    }

    /// A desugared (`is_async=false`) function item whose `sig.output` is `output`.
    // Fixture builder: owned JSON args mirror serde_json::json! ergonomics.
    #[allow(clippy::needless_pass_by_value)]
    fn desugared_fn(output: serde_json::Value) -> serde_json::Value {
        serde_json::json!({
            "header": { "is_const": false, "is_unsafe": false, "is_async": false, "abi": "Rust" },
            "sig": {
                "inputs": [ [ "self", { "borrowed_ref": { "lifetime": null, "mutable": false,
                    "type_": { "generic": "Self" } } } ] ],
                "output": output
            }
        })
    }

    #[test]
    fn wall4_positive_recognises_and_extracts_output_from_constraints() {
        // §1 shape: Pin<Box<dyn Future<Output=Result<i64,String>> + Send>>.
        let boxed = async_trait_box(
            result_i64_string(),
            "::core::future::Future",
            4,
            &[("::core::marker::Send", 6)],
        );
        let out = async_trait_future_output(&boxed)
            .expect("canonical async_trait future box must be recognised");
        // C4 / make-or-break: Output is the UNWRAPPED Result<i64,String>, NOT `()`
        // and NOT the `equality` wrapper. Render to the Ipe type and assert it is
        // `Result String i64` (so de-async → `Task String i64`, never `Task Error ()`).
        let ipe = rustdoc_type_to_ipe(out, &HashMap::new());
        assert_eq!(
            ipe, "Result String Int",
            "Output must be the real T, not (): {ipe}"
        );
    }

    #[test]
    fn wall4_de_async_clone_forces_is_async_and_rewrites_output_without_mutation() {
        let boxed = async_trait_box(
            result_i64_string(),
            "::core::future::Future",
            4,
            &[("::core::marker::Send", 6)],
        );
        let fn_data = desugared_fn(boxed);
        // Pre-condition: shared node is is_async=false with a Pin output.
        assert_eq!(fn_data["header"]["is_async"], serde_json::json!(false));
        let clone = de_async_clone(&fn_data).expect("async_trait fn must de-async");
        // C5: the CLONE has is_async=true and the unwrapped output …
        assert_eq!(clone["header"]["is_async"], serde_json::json!(true));
        assert_eq!(
            rustdoc_type_to_ipe(&clone["sig"]["output"], &HashMap::new()),
            "Result String Int"
        );
        // … and the SHARED index node is UNMUTATED (C5 — clone isolation).
        assert_eq!(fn_data["header"]["is_async"], serde_json::json!(false));
        assert!(fn_data["sig"]["output"].get("resolved_path").is_some());
        assert_eq!(
            fn_data["sig"]["output"]["resolved_path"]["path"],
            "::core::pin::Pin"
        );
    }

    #[test]
    fn wall4_parse_fn_item_binds_async_trait_method_as_effectful_task() {
        // End-to-end through parse_fn_item: the desugared method binds as an
        // EFFECTFUL fn whose result Ipe type is `Task String i64`, with NO drop.
        let boxed = async_trait_box(
            result_i64_string(),
            "::core::future::Future",
            4,
            &[("::core::marker::Send", 6)],
        );
        let fn_data = desugared_fn(boxed);
        // The de-async'd method routes through the async Send gates (C1c): the
        // receiver MUST be provably Send. Register `Db` as provably-Send for the
        // call (mirrors what `collect_provably_send_recv_names` proves from a real
        // `Send + Sync` struct like firestore's `FirestoreDb`), then restore.
        PROVABLY_SEND_RECV_NAMES.with(|c| {
            c.borrow_mut().insert("Db".to_string());
        });
        let f = parse_fn_item("op", &fn_data, &HashMap::new(), Some(("Db", "Db")));
        PROVABLY_SEND_RECV_NAMES.with(|c| c.borrow_mut().clear());
        let f = f.expect("async_trait method must bind");
        assert_eq!(f.effect, "effectful", "is_async must be forced → effectful");
        let ret = f.results.first().expect("a result param");
        // The de-async'd output is the REAL `Result<i64,String>` (rendered Ipe
        // `Result String Int`); effect=effectful means the codegen lifts it to
        // `Task String Int`. The make-or-break: it is the real T, NEVER `()`
        // (which would mean the stale `bindings` reader silently de-async'd to
        // `Task Error ()`).
        assert_eq!(
            ret.ipe_type, "Result String Int",
            "Output must be the real Result<i64,String>, not (): {:?}",
            ret.ipe_type
        );
        assert_ne!(ret.ipe_type, "()", "C4: must not silently collapse to unit");
    }

    #[test]
    fn wall4_parse_fn_item_async_trait_with_non_send_receiver_drops() {
        // §7 check #4: is_async=true actually FIRES the receiver Send gate (C1c).
        // A receiver NOT in PROVABLY_SEND_RECV_NAMES drops `async-future-not-send`
        // (would be E0277 at spawn) — proving de-async re-routes through the gate.
        let boxed = async_trait_box(
            result_i64_string(),
            "::core::future::Future",
            4,
            &[("::core::marker::Send", 6)],
        );
        let fn_data = desugared_fn(boxed);
        // No Send registration for `RcDb` → must drop.
        let f = parse_fn_item("op", &fn_data, &HashMap::new(), Some(("RcDb", "RcDb")));
        assert!(
            f.is_none(),
            "a non-Send receiver async_trait method must drop"
        );
    }

